function Tob(a,b){var c=J(a),d=b;for(b=0;;){if(d>=c)return c;switch(a.charAt(d)){case "(":case "[":case "{":b+=1;d+=1;continue;case ")":case "]":case "}":if(F.h(b,1))return d+1;--b;d+=1;continue;case '"':var e=function(){for(var f=d+1;;){if(f>=c)return c;if(F.h("\\",a.charAt(f)))f+=2;else{if(F.h('"',a.charAt(f)))return f+1;f+=1}}}();d=e;continue;case ";":d=e=function(){var f=a.indexOf("\n",d);return 0>f?c:f}();continue;case "\\":d+=2;continue;default:d+=1}}}
