var pBb=new bn(function(){return Vj.h(cf,Im(/\(defn \^:renderer ([^\s()]+)/,';; RecDep standard library — ordinary Clojure, evaluated in SCI\'s `user`\n;; namespace once per page and shared by every sheet and every grid.\n;;\n;; It isn\'t saved with sheets and can\'t be edited in the app: a grid\'s own\n;; library (the Library tab) can redefine any of these names for its cells\n;; and the grids inside it.\n;;\n;; Layout: a line `;;; # Title` starts a section of the reference shown in\n;; the Library tab; the `;;; ` lines straight after it are its introduction.\n;; Every var needs a docstring (a test checks).\n\n;;; # Settings\n;;; Values the engine reads from the library. Redefine one in the top\n;;; grid\'s library to change it for the whole sheet.\n\n(def time-limit-ms\n  "How long one cell\'s formula (or a renderer) may run, in milliseconds,\n  before it\'s stopped with #TIME. Catches endless loops and sequences.\n  Redefine it in the top grid\'s library to change it for the sheet:\n  (def time-limit-ms 5000)."\n  1000)\n\n(def iterate-cycles\n  "Whether cycles (cells whose formulas read each other, or themselves)\n  are worked out by iterating, as Excel\'s iterative calculation does,\n  instead of being #CYCLE errors: false, true (at most 100 rounds,\n  stopping once no cell changes by more than 0.001), or a map changing\n  those, {:max-iterations 500 :max-change 1e-6}. Define it in a grid\'s\n  library for that grid and the grids inside it, in the top grid\'s for\n  the whole sheet, or in My library for every sheet; the nearest\n  definition wins. A cell menu\'s Iterate cycles in this grid writes it.\n  A cycle iterates only if every grid it passes through allows it."\n  false)\n\n(def custom-units\n  "Units of the sheet\'s own, beside the built-in ones (see Units): a map\n  of names to definitions. A definition is a number in units already\n  known — \\"201.168 m\\", \\"14 d\\", \\"12 item\\" (they can use each other) —\n  or :kind, a kind of quantity of its own that doesn\'t convert to anything\n  else, such as people or items: then $/person and items/h work, and\n  adding people to dollars is flagged. {:as \\"1000 g\\" :prefixes \\"kM\\"} or\n  {:kind true :prefixes \\"k\\"} also takes SI prefixes. Define it in the\n  top grid\'s library for the whole sheet (saved with it), in My library\n  for every sheet, or in a grid\'s library for that grid and the grids\n  inside it; the nearest definition wins, as for functions:\n  (def custom-units {\\"furlong\\" \\"201.168 m\\" \\"person\\" :kind}).\n  Mistakes show as that library\'s error."\n  {})\n\n(def preferred-units\n  "Units to show worked-out results in (see Units): a vector of units. A\n  formula\'s result shows in the preferred unit of its kind; else each part\n  of its unit of a base kind does: with [\\"m\\" \\"s\\"], 240 km + 1000 m shows\n  241000 m and km/h shows m/s. A temperature change shows in the Δ of a\n  preferred scale (°F: Δ°F). Numbers typed with a unit show as typed, and\n  a cell\'s own unit or its column\'s always wins. Define it in the top\n  grid\'s library for the whole sheet, in My library for every sheet, or\n  in a grid\'s library for that grid and the grids inside it (the nearest\n  definition wins): (def preferred-units [\\"m\\" \\"kg\\"])."\n  [])\n\n;;; # Formula helpers\n;;; For cell formulas, beside Excel\'s functions (SUM, AVERAGE, MAX,\n;;; ROUND …, above). Ranges are always 2-D: a vector of rows, each a\n;;; vector of values (nil for empty cells). A grid\'s value is a map of its\n;;; cells\' values. These helpers take either, and single values, and skip\n;;; what isn\'t a number.\n\n(defn cells\n  "Flatten a range, a grid\'s map of values, or a single value into a seq\n  of its non-nil values: (cells A1:B3), (cells B5) for the grid in B5."\n  [x]\n  (cond (map? x) (mapcat cells (vals x))\n        (sequential? x) (mapcat cells x)\n        (nil? x) ()\n        :else (list x)))\n\n(defn nums\n  "All the numbers in the arguments (ranges, grids or single values), in\n  order; text and empty cells are skipped: (nums A1:A10 C1)."\n  {:units :same}\n  [\x26 xs]\n  (filter number? (mapcat cells xs)))\n\n(defn clamp\n  "x limited to lo..hi: (clamp 12 0 10) → 10."\n  {:units :same}\n  [x lo hi]\n  (max lo (min hi x)))\n\n(defn column\n  "First column of a range, as a vector: (column A1:B5) → [A1 … A5]."\n  [rng]\n  (mapv first rng))\n\n(defn row-of\n  "First row of a range, as a vector: (row-of A1:E2) → [A1 … E1]."\n  [rng]\n  (vec (first rng)))\n\n;;; # Tables\n;;; A table is a sequence of row maps, one map per row keyed by its\n;;; headers: what a grid with headers gives as its value ([{:item "apple"\n;;; :qty 3} …]), and what spills with a header row. Clojure\'s own\n;;; functions work on it — (filter #(\x3e (:qty %) 2) orders), (map :qty\n;;; orders) — and these add sorting in Excel\'s order, filtering by a\n;;; column, and summaries. A column is a keyword (:qty), a number counted\n;;; from 1 for rows of a range, or a function of the row. For ranges,\n;;; Excel\'s SORT, FILTER, UNIQUE, GROUPBY and PIVOTBY do the same.\n\n(defn- order-rank\n  "Where a value comes in Excel\'s sort order: numbers, text, logicals."\n  [x]\n  (cond (number? x) 0 (string? x) 1 (boolean? x) 2 :else 3))\n\n(defn- excel-compare\n  "Excel\'s sort order: numbers, text ignoring case, logicals, the rest."\n  [a b]\n  (cond (and (vector? a) (vector? b))\n        (or (first (remove zero? (map excel-compare a b))) 0)\n        (not\x3d (order-rank a) (order-rank b)) (compare (order-rank a) (order-rank b))\n        (string? a) (compare (clojure.string/lower-case a) (clojure.string/lower-case b))\n        (\x3d 3 (order-rank a)) (compare (str a) (str b))\n        :else (compare a b)))\n\n(defn- column-fn\n  "A function reading column k of a row: a keyword of a row map, a number\n  (from 1) of a row vector, several as a vector, or a function."\n  [k]\n  (cond (keyword? k) #(get % k)\n        (number? k) #(get % (dec k))\n        (vector? k) (apply juxt (map column-fn k))\n        (ifn? k) k\n        :else (throw (ex-info (str "a column is a keyword, a number (from 1) or a function, got " (pr-str k)) {}))))\n\n(defn sort-rows\n  "The rows of a table (or of a range) sorted by column k, in Excel\'s\n  order — numbers, then text ignoring case, then TRUE / FALSE — with\n  empty values last either way: (sort-rows orders :qty),\n  (sort-rows orders :qty :desc), (sort-rows orders [:region :qty]),\n  (sort-rows A2:C9 2)."\n  ([rows k] (sort-rows rows k :asc))\n  ([rows k order]\n   (let [g (column-fn k)\n         blank? #(let [x (g %)] (or (nil? x) (and (vector? x) (every? nil? x))))\n         s (sort-by g excel-compare (remove blank? rows))]\n     (vec (concat (if (\x3d order :desc) (reverse s) s) (filter blank? rows))))))\n\n(defn filter-rows\n  "The rows of a table (or of a range) that pass: (filter-rows orders\n  #(\x3e (:qty %) 2)) tests each row; with a column, its value —\n  (filter-rows orders :qty pos?), (filter-rows orders :region \\"north\\")\n  (text ignoring case), (filter-rows orders :status #{:todo :doing})."\n  ([rows pred] (filterv #(boolean (pred %)) rows))\n  ([rows k test]\n   (let [g (column-fn k)\n         p (cond (string? test) #(and (string? %) (\x3d (clojure.string/lower-case %) (clojure.string/lower-case test)))\n                 (or (keyword? test) (number? test) (boolean? test) (nil? test)) #(\x3d % test)\n                 (ifn? test) test\n                 :else #(\x3d % test))]\n     (filterv #(boolean (p (g %))) rows))))\n\n(defn group-rows\n  "A table summarised by column k: a row map per distinct value of k\n  (sorted), holding k and, for each entry of aggs, a function of the\n  group\'s values of the column with that key (empty ones left out):\n  (group-rows orders :region {:qty SUM :price AVERAGE}). An entry can name\n  another column, [column f]: {:orders [:item COUNTA]}. Without aggs, the\n  count of rows: (group-rows orders :region) → [{:region \\"north\\" :count\n  3} …]. k can be a vector of keys."\n  ([rows k] (group-rows rows k {:count [identity count]}))\n  ([rows k aggs]\n   (let [ks (if (vector? k) k [k])\n         g (column-fn k)]\n     (when-not (every? keyword? ks)\n       (throw (ex-info "group-rows: group by keywords (columns of a table)" {})))\n     (vec (for [[kv group] (sort-by key excel-compare (group-by g rows))]\n            (merge (zipmap ks (if (vector? k) kv [kv]))\n                   (into {} (for [[out spec] aggs\n                                  :let [[col f] (if (vector? spec) spec [out spec])\n                                        cg (column-fn col)]]\n                              [out (f (vec (remove nil? (map cg group))))]))))))))\n\n(defn pivot-rows\n  "A cross-table of a table: a row per distinct value of row-k, a column\n  per distinct value of col-k (both sorted), and in each cell f of the\n  val-k values of the rows with both (empty when there are none):\n  (pivot-rows orders :region :month :qty SUM). The result is a range\n  with a header row; it spills."\n  [rows row-k col-k val-k f]\n  (let [rg (column-fn row-k) cg (column-fn col-k) vg (column-fn val-k)\n        by (group-by (juxt rg cg) rows)\n        rks (sort excel-compare (distinct (map rg rows)))\n        cks (sort excel-compare (distinct (map cg rows)))]\n    (into [(into [(if (keyword? row-k) (name row-k) "")] cks)]\n          (for [r rks]\n            (into [r] (for [c cks]\n                        (when-let [g (seq (get by [r c]))]\n                          (f (vec (remove nil? (map vg g)))))))))))\n\n(defn as-grid\n  "A result laid out in a grid of its own, in the formula\'s cell, as big\n  as the result: (as-grid (filter-rows orders :region \\"north\\")). The\n  grid\'s cells are cells — select them, refer to them (north\x3eqty), give\n  them formats and widths, show it with (grid-view) — and it grows and\n  shrinks with the result. A table gets a header row. Its values can\'t\n  be typed over: change the formula, or convert it to a plain grid (cell\n  menu). Options: :columns [:item :qty], a table\'s columns in that\n  order (kept when it\'s empty); :renders {[0 2] renderer}, cells of the\n  grid that draw themselves, by [row column] from 0; :show rows, cells\n  to lay out instead of the value (which stays the cell\'s value: it must\n  be a collection, or it\'s put in a vector); :headers true or false, row\n  1 as headers; :widths {0 120}, column widths until the grid has its own,\n  and :heights {1 200}, row heights likewise; :spans {[1 0] [4 3]}, cells\n  that draw over a block of rows × columns from them (the covered cells\n  must be empty), for a chart or a grid bigger than a cell. panel builds\n  on these."\n  ([rows] (as-grid rows {}))\n  ([rows {:keys [columns renders show widths heights spans] :as opts}]\n   (let [v (cond show (cond (coll? rows) rows (nil? rows) [] :else [rows])\n                 (map? rows) [rows]\n                 (nil? rows) []\n                 (vector? rows) rows\n                 (sequential? rows) (vec rows)\n                 :else [[rows]])]\n     (cond-\x3e (vary-meta v assoc :recdep/as-grid true\n                        :recdep/columns (seq columns) :recdep/renders renders\n                        :recdep/show (when show (vec show)) :recdep/widths widths\n                        :recdep/heights heights :recdep/spans spans)\n       (contains? opts :headers) (vary-meta assoc :recdep/headers (boolean (:headers opts)))))))\n\n;;; # Dates and times\n;;; Dates and times are numbers, as in Excel: the days since 30 December\n;;; 1899, with the time of day as the fraction — 2026-11-07 is 46333,\n;;; noon on it 46333.5, 14:30 on its own 0.604…. So (+ A1 7) is a week\n;;; later and (- B1 A1) the days between. A cell\'s number format makes the\n;;; number look like a date ("yyyy-mm-dd", "d mmm yyyy", "h:mm AM/PM").\n;;; Type a date, a time or both into a cell as you\'d write them, without\n;;; quotes: 2026-11-07, 14:30 (or 2:30 pm), 2026-11-07 14:30; the cell\n;;; gets a date format as written. A formula starting with a date function\n;;; (TODAY, DATE, EDATE, add-time…) or on a date cell gets one too. Inside\n;;; a formula write a date as text, "2026-11-07": arithmetic and the date\n;;; functions read it. Ctrl-; puts today\'s date in a cell (or in the\n;;; formula you\'re writing), Ctrl-Shift-; the time now. No time zones are\n;;; applied. Excel\'s date functions (YEAR, EDATE, NETWORKDAYS…) take the\n;;; same numbers; pick dates with date-input, time-input and\n;;; date-time-input.\n\n;;; # Units\n;;; A cell can say what its number measures: type 5 km, 12.5 m/s, $40 or\n;;; 20 °C, or give the selection a unit in the format bar\'s unit field (a\n;;; whole column with its header). The value is a plain number in the base\n;;; unit of its kind (metres, kilograms, kelvin, days for time, each\n;;; currency as itself), so arithmetic is right whatever the units: 1 km +\n;;; 500 m shows 1.5 km. A plain number typed into a cell with a unit is in\n;;; that unit. A formula\'s unit is worked out from it — km/h from a length\n;;; over a time — and mistakes are flagged with an amber corner: adding km\n;;; to kg, a plain number to a length, two temperatures. In a formula write\n;;; a quantity as text, as dates are: (+ A1 "10 min"), (\x3e A1 "5 km"). °C\n;;; and °F are temperatures; a change of temperature is Δ°C (typed\n;;; delta-degC). A function says how units pass through it with :units\n;;; metadata, (defn total {:units :same} [\x26 xs] …): :same, :plain,\n;;; :plain-args, {:from 0} and the others in the design notes; without it\n;;; its result\'s unit is unknown, and nothing is flagged.\n\n;;; # Filling down and across\n;;; A column or row of values from one formula: numbers, dates, times,\n;;; month and weekday names, numbered headings, or any list. The result\n;;; spills (see Spilling) from the formula\'s cell to the bottom (down) or\n;;; the right-hand edge (across) of its grid, so there\'s nothing to count:\n;;; grow the grid and the fill grows with it. Anything already in the way\n;;; makes it #SPILL, naming the cell. To stop sooner, give a list:\n;;; (down (range 1 11)).\n\n(defn rows-to-end\n  "How many rows there are from this cell to the bottom of its grid,\n  counting its own: 3 in row 28 of a 30-row grid. Cell formulas only."\n  []\n  (let [{:keys [row rows]} (here)] (inc (- rows row))))\n\n(defn cols-to-end\n  "How many columns there are from this cell to the right-hand edge of\n  its grid, counting its own. Cell formulas only."\n  []\n  (let [{:keys [col cols]} (here)] (inc (- cols col))))\n\n(def ^:private day-names\n  "Weekday names, short and long, Monday first (for series)."\n  [["Mon" "Tue" "Wed" "Thu" "Fri" "Sat" "Sun"]\n   ["Monday" "Tuesday" "Wednesday" "Thursday" "Friday" "Saturday" "Sunday"]])\n\n(def ^:private month-names\n  "Month names, short and long (for series)."\n  [["Jan" "Feb" "Mar" "Apr" "May" "Jun" "Jul" "Aug" "Sep" "Oct" "Nov" "Dec"]\n   ["January" "February" "March" "April" "May" "June" "July" "August"\n    "September" "October" "November" "December"]])\n\n(defn- name-cycle\n  "[names i case-fn] if s is one of the names in `lists` (any case)."\n  [lists s]\n  (let [lower (clojure.string/lower-case s)]\n    (some (fn [names]\n            (when-let [i (first (keep-indexed (fn [i n] (when (\x3d lower (clojure.string/lower-case n)) i)) names))]\n              [names i (cond (\x3d s lower) clojure.string/lower-case\n                             (\x3d s (clojure.string/upper-case s)) clojure.string/upper-case\n                             :else identity)]))\n          lists)))\n\n(defn- pad-to\n  "n as text, zero-padded to `width` digits."\n  [n width]\n  (let [s (str n)]\n    (str (apply str (repeat (- width (count s)) "0")) s)))\n\n(defn series\n  "An endless sequence carrying on from `start`, as Excel\'s fill does:\n  (series 1) → 1 2 3 …; (series 0 5) → 0 5 10 …; (series \\"Jan\\") → Jan\n  Feb … Dec Jan …; (series \\"Mon\\") → weekdays (short or long names, in\n  the case written); (series \\"Q1\\") → Q1 Q2 Q3 Q4 Q1 …; (series \\"Week\n  1\\") → Week 2, Week 3 … (any text ending in a number). A date steps by\n  days, a time by hours: (series \\"2026-01-05\\" 7) → every Monday,\n  (series \\"09:00\\" 30 :minutes) → every half hour, (series \\"2026-01-31\\"\n  1 :months) → the last day of each month; a unit alone steps by one of\n  it: (series \\"2026-01-01\\" :weeks). Dates come out as serial numbers\n  (the cell gets a date format); a number with a unit is taken as a\n  date: (series A1 1 :months). Other values repeat. Usually given\n  to down or across, which stop at the grid\'s edge; elsewhere take what\n  you need: (take 12 (series \\"Jan\\"))."\n  ([start] (series start 1))\n  ([start step] (if (keyword? step) (series start 1 step) (series start step nil)))\n  ([start step unit]\n   (let [k (range)\n         kind (date-kind start)\n         s (when (string? start) (clojure.string/trim start))]\n     (cond\n       (and (number? start) unit) (map #(add-time start (* % step) unit) k)\n       (number? start) (map #(+ start (* % step)) k)\n       kind (let [t (parse-date start)]\n              (map #(add-time t (* % step) (or unit (if (\x3d kind :time) :hours :days))) k))\n       (nil? s) (repeat start)\n       :else\n       (if-let [[names i case-fn] (or (name-cycle day-names s) (name-cycle month-names s))]\n         (map #(case-fn (nth names (mod (+ i (* % step)) (count names)))) k)\n         (if-let [[_ q n] (re-matches #"([Qq])([1-4])" s)]\n           (map #(str q (inc (mod (+ (dec (str-\x3enum n)) (* % step)) 4))) k)\n           (if-let [[_ prefix digits] (re-matches #"(?s)(.*?)(\\d+)" s)]\n             (let [n (str-\x3enum digits)\n                   width (if (\x3d \\0 (first digits)) (count digits) 0)]\n               (map #(str prefix (pad-to (+ n (* % step)) width)) k))\n             (repeat start))))))))\n\n(defn- fill-from\n  "What down and across lay out: a collection as it is, anything else as\n  the series starting from it."\n  [x more]\n  (if (and (coll? x) (empty? more)) x (apply series x more)))\n\n(defn down\n  "A column of values from this cell to the bottom of the grid, spilling\n  into the cells below. (down) → 1, 2, 3 …; (down 0) starts at 0;\n  (down 10 10) → 10, 20, 30 …; (down \\"Jan\\"), (down \\"2026-01-05\\" 7),\n  (down \\"09:00\\" 30 :minutes): what series gives for the same arguments.\n  A list is laid out as it is, as far as the bottom: (down (range 28)),\n  (down [\\"Red\\" \\"Green\\" \\"Blue\\"]), (down (cycle [\\"A\\" \\"B\\"])). Cell\n  formulas only."\n  ([] (down 1))\n  ([x \x26 more] (mapv vector (take (rows-to-end) (fill-from x more)))))\n\n(defn across\n  "A row of values from this cell to the right-hand edge of the grid,\n  spilling into the cells to the right: headings such as (across \\"Jan\\"),\n  (across \\"Q1\\"), (across \\"2026-01-05\\" 7), or a list laid out as it is:\n  (across [\\"Name\\" \\"Qty\\" \\"Price\\"]). Takes what down takes. Cell\n  formulas only."\n  ([] (across 1))\n  ([x \x26 more] [(vec (take (cols-to-end) (fill-from x more)))]))\n\n;;; # Validation\n;;; Predicates for validation rules, which sit among a grid\'s formats:\n;;; {:area "B2:B20" :valid "(one-of D2:D9)" :msg "one of the sizes"}.\n;;; Any function of the value will do (pos-int?, string?, #(\x3c 0 % 100),\n;;; a set); these also tell the controls in those cells what to offer —\n;;; dropdown and radio their options, number-input, slider and stepper\n;;; their bounds — and say why a value fails. References in :valid are\n;;; read from each cell checked, as a formula there would read them.\n\n(defn one-of\n  "Validation: the value must be one of the options, given as values or\n  as ranges and collections of them (empty cells skipped): (one-of D2:D9),\n  (one-of :low :mid :high). dropdown and radio offer the options."\n  [\x26 options]\n  (let [opts (vec (distinct (mapcat #(if (coll? %) (cells %) (when (some? %) [%])) options)))\n        members (set opts)]\n    (with-meta (fn [v] (contains? members v))\n      {:options opts\n       :msg (str "must be one of " (clojure.string/join ", " (map pr-str (take 6 opts)))\n                 (when (\x3e (count opts) 6) ", …"))})))\n\n(defn between\n  "Validation: a number from lo to hi, both included; nil for no bound:\n  (between 0 100), (between 0 nil). Dates are numbers, so bounds can be\n  dates too: (between \\"2026-01-01\\" \\"2026-12-31\\"), and quantities in a\n  cell with a unit, whose values are in base units: (between \\"0 km\\"\n  \\"10 km\\"). number-input, slider and stepper keep to the bounds."\n  [lo-bound hi-bound]\n  (let [read (fn [b] (if (string? b) (or (parse-date b) (let [n (VALUE b)] (when (number? n) n))) b))\n        lo (read lo-bound)\n        hi (read hi-bound)\n        what (if (some #(and (string? %) (parse-date %)) [lo-bound hi-bound]) "a date" "a number")]\n    (with-meta (fn [v] (and (number? v) (or (nil? lo) (\x3c\x3d lo v)) (or (nil? hi) (\x3c\x3d v hi))))\n      {:min lo :max hi\n       :msg (cond (and lo hi) (str "must be " what " from " lo-bound " to " hi-bound)\n                  lo (str "must be " what ", at least " lo-bound)\n                  hi (str "must be " what ", at most " hi-bound)\n                  :else "must be a number")})))\n\n(defn all-of\n  "Validation: every predicate must hold, and the first that fails says\n  why: (all-of int? (between 1 10)). Controls get what each one tells\n  them."\n  [\x26 preds]\n  (with-meta (fn [v] (every? #(% v) preds)) {:all preds}))\n\n;;; # Writing to cells\n;;; For interactive renderers. Their event handlers write literals into\n;;; cells, and the dependency graph does the rest. A ref is a quoted\n;;; symbol or a string, relative to the renderer\'s cell: \'r1, "B5".\n\n(defn set-cell!\n  "Write v as a literal into the cell `ref` refers to, from a renderer\'s\n  event handler: (set-cell! ctx \'r1 42), (set-cell! ctx \\"B5\\" \\"done\\")."\n  [ctx ref v]\n  ((:set! ctx) ref v))\n\n(defn update-cell!\n  "Replace the cell `ref` refers to with (f its-current-value), from a\n  renderer\'s event handler: (update-cell! ctx \'d1 inc)."\n  [ctx ref f]\n  ((:update! ctx) ref f))\n\n(defn set-self!\n  "Write v as a literal into the renderer\'s own cell (what slider, toggle\n  and the other inputs do): (set-self! ctx true)."\n  [ctx v]\n  ((:set! ctx) \'u0 v))\n\n(defn set-option!\n  "From a renderer in a grid a formula makes (as-grid, filter-view): set\n  `path` of the formula\'s options — the map that is its last argument —\n  to v, rewriting the formula (nil removes it): (set-option! ctx\n  [:region] \\"North\\"). The formula is evaluated again, and its grid\n  drawn again with the new options."\n  [ctx path v]\n  (if-let [f (:set-option! ctx)]\n    (f path v)\n    (throw (ex-info "set-option! works in a grid made by a formula (as-grid)" {}))))\n\n(defn option-ctx\n  "ctx for a control drawn inside another renderer, so that what it\n  writes to its own cell (set-self!) sets option `path` of the formula\n  instead: ((dropdown [\\"a\\" \\"b\\"]) current (option-ctx ctx [:pick])).\n  How a view composes the interactive renderers into its controls."\n  [ctx path]\n  (assoc ctx :set! (fn [_ v] (set-option! ctx path v))))\n\n;; ---------------------------------------------------------------------------\n;; What the Renderer field\'s gallery reads from a renderer\'s metadata\n;;\n;; A renderer may say how the gallery should offer it, beside its\n;; definition (the attr map after the docstring): :accepts, the kinds of\n;; value it\'s for (#{:number}; also :date :time :text :bool :empty :seq\n;; :map :rows :table :grid :hiccup); :suggest, a function of what the\n;; gallery knows of the value giving the calls to offer (["(heat 0 10)"]);\n;; :compares true, for a renderer comparing a value with others (not\n;; offered for one number alone); :showcase true, for one showing off a\n;; single value (not offered for several cells); :writes-own true, for a\n;; control writing its own cell (only offered on a value typed in); :aka,\n;; words to find it by ("heatmap colour scale"). The value\'s information\n;; (:suggest\'s argument) is :v, :kinds, :range {:range "B2:B9" :lo :hi}\n;; (the numbers around it), :bounds {:lo :hi :lo-src :hi-src} (for an\n;; indicator: the range\'s MIN and MAX as references, else round numbers),\n;; :format, :constraint (its validation), :label (a caption), :choices\n;; (the values around it), and :nice and :num, functions rounding up to\n;; 1, 2 or 5 × a power of ten and writing a number short.\n\n(defn- choice-sources\n  "What a drop-down or radio buttons is offered as: the cell\'s\n  validation\'s options when it has some; else the values around it (the\n  column\'s, or the selection\'s); else the value and two more to edit."\n  [renderer {:keys [v constraint choices]}]\n  (cond\n    (seq (:options constraint)) [renderer]\n    (\x3c\x3d 2 (count choices)) [(str "(" renderer " " (pr-str (vec choices)) ")")]\n    (string? v) [(str "(" renderer " " (pr-str [v "Option 2" "Option 3"]) ")")]\n    (nil? v) [(str "(" renderer " [\\"Low\\" \\"Medium\\" \\"High\\"])")]))\n\n;;; # Renderers: numbers and text\n;;; A cell\'s look comes from four settings that work together, each with\n;;; its own job. Its number format says how a number is written —\n;;; decimals, currency, percentages, dates — as an Excel format code\n;;; ("#,##0.00", "0.0%", "d-mmm-yy", "#,##0;[Red]-#,##0", "0.0\\" pts\\""),\n;;; set in the format bar\'s format field (or :format in a format rule);\n;;; without one a number is shown as Excel\'s General does. Its unit says\n;;; what the number measures (see Units). Its style is how the cell looks:\n;;; bold, colours, alignment. Its renderer says what kind of thing the\n;;; value is drawn as — a bar, a dial, a link, a chart, a control — and\n;;; every number a renderer writes (a data bar\'s label, a KPI, a slider\'s\n;;; reading, a chart\'s tooltip) is written in the cell\'s format and unit,\n;;; in the cell\'s style, so choosing a renderer never undoes them. The\n;;; style\'s text colour is also the colour a renderer draws in: a gauge\'s\n;;; arc, a progress or data bar, a sparkline, bars, a heat fill, a\n;;; chart\'s marks (blue without one; see ink). Negative bars stay red, and\n;;; colours that mean something (a trend\'s arrow, a traffic light, a\n;;; badge\'s) stay theirs.\n;;;\n;;; A renderer is (fn [value ctx] hiccup); give a cell one in its Renderer\n;;; field, or a whole column, row or range in Formats. Some are renderers\n;;; themselves (write `plain`), others make one from options (write\n;;; `(data-bar 25)`): each docstring says which, though brackets are\n;;; optional where there are no options (`grid-view` is `(grid-view)`).\n;;; Options can read cells: `(data-bar (MAX B2:B7))`. As in a formula, a\n;;; number in the options is in base units (metres, days…) and a quantity\n;;; is written as text: (data-bar "10 km"). Both are marked ^:renderer,\n;;; which is what the Renderer field offers as you type; mark your own the\n;;; same way, (defn ^:renderer my-badge [v ctx] …), and write numbers with\n;;; (number-text v ctx) or plain so they show as the cell says. ctx has\n;;; :address, the cell\'s :value, its number :format (nil for General), its\n;;; :unit (nil for none), its :style (a CSS map, already on the cell),\n;;; :set! and :update! (see Writing to cells), :go-to! (called with\n;;; reference text, as a formula in the cell would write it, it selects\n;;; that cell: what [[B6\x3eC9]] links in markdown use), and, in cells with a\n;;; validation rule, :constraint: {:options :min :max :step} as far as its\n;;; predicates tell, and :msg when the value fails.\n\n(defn- formatted\n  "Hiccup for a number, boolean, error value or text shown in number\n  format `code` (nil: General), coloured as the format says; a number in\n  `unit`, if given."\n  [v code unit]\n  (let [{:keys [text color]} (format-value v code unit)\n        tag (cond (xl-error? v) :span.xl-error\n                  (number? v) :span.num\n                  (boolean? v) :span.xl-bool\n                  :else :span.str)]\n    (if color [tag {:style {:color color}} text] [tag text])))\n\n(defn ^:renderer plain\n  "Renderer: the value as text, styled by type. Numbers, TRUE / FALSE and\n  error values are shown in the cell\'s number format (General when it has\n  none, as Excel shows them: 0.1 + 0.2 is 0.3, a long number is rounded\n  to fit), in the cell\'s unit if it has one (1.5 km, $40); text as it\n  is, through the format\'s text section if it has one; keywords; other\n  data printed as Clojure. nil shows nothing. The other renderers write\n  their numbers with it. Use as: plain."\n  [v ctx]\n  (let [code (:format ctx)]\n    (cond (nil? v)      [:span]\n          (or (number? v) (boolean? v) (xl-error? v)) (formatted v code (:unit ctx))\n          (string? v)   (if code (formatted v code nil) [:span.str v])\n          (keyword? v)  [:span.kw (str v)]\n          :else         [:span.code (pr-str v)])))\n\n(defn number-text\n  "x as text the way its cell shows numbers: in ctx\'s number format and\n  unit (General without a format). For renderers of your own, and for\n  hover titles: (number-text 1500 {:unit \\"km\\"}) → \\"1.5 km\\"."\n  [x ctx]\n  (:text (format-value x (:format ctx) (:unit ctx))))\n\n(defn- shown-number\n  "Number v as a number in the cell\'s unit (v itself without one, or with\n  one that isn\'t a unit)."\n  [v ctx]\n  (if-let [u (:unit ctx)] (try (in-unit v u) (catch :default _ v)) v))\n\n(defn- short-number\n  "x as text for a chart\'s labels and titles: in the cell\'s number format\n  and unit when it has a format, else to three significant digits (in\n  its unit)."\n  [x ctx]\n  (let [shown (when (number? x) (shown-number x ctx))\n        x (if (or (:format ctx) (nil? shown) (zero? shown))\n            x\n            (let [r (ROUND shown (max 0 (- 2 (INT (LOG (ABS shown))))))]\n              (if (\x3d shown x) r (with-unit r (:unit ctx)))))]\n    (number-text x ctx)))\n\n(defn- unit-step\n  "One of the cell\'s shown unit, in base units (1 without a unit): a\n  control\'s default step, so a stepper in a km cell steps by a km."\n  [ctx]\n  (if-let [u (:unit ctx)]\n    (try (- (with-unit 1 u) (with-unit 0 u)) (catch :default _ 1))\n    1))\n\n(defn- option-number\n  "A renderer option as a number in base units: a number as it is, a\n  quantity written as text (\\"10 km\\", \\"$5\\") as its value."\n  [x]\n  (if (string? x) (VALUE x) x))\n\n(defn- format-symbol\n  "The currency symbol number format `code` writes: $ for \\"$#,##0\\", €\n  for \\"[$€]#,##0.00\\"; nil for none."\n  [code]\n  (when (string? code)\n    (or (second (re-find #"\\[\\$([^\\]\\-]+)" code))\n        (when (re-find #"^[^\\"]*\\$" code) "$"))))\n\n(defn- number-view\n  "Renderer for numbers written by (format-number n opts), n the number in\n  the cell\'s unit, with the unit, or the currency symbol of the cell\'s\n  format, and in its format\'s colour (a [Red] section); anything else is\n  shown plain. Behind compact."\n  [opts]\n  (fn [v ctx]\n    (if (number? v)\n      (let [t (format-number (shown-number v ctx) opts)\n            sym (format-symbol (:format ctx))\n            t (if (and sym (not (:unit ctx)))\n                (if (clojure.string/starts-with? t "-") (str "-" sym (subs t 1)) (str sym t))\n                (unit-text t (:unit ctx)))\n            color (:color (format-value v (:format ctx)))]\n        (if color [:span.num {:style {:color color}} t] [:span.num t]))\n      (plain v ctx))))\n\n(defn ^:renderer compact\n  "Renderer maker: big numbers in short form, which no number format can\n  do. (compact) → 1.2K, 5.6M, 3B; (compact 2) allows up to 2 decimals →\n  1.23K. In the cell\'s unit (1.2K km) or its format\'s currency ($5.6M)."\n  {:accepts #{:number} :aka "thousands millions K M short big number"\n   :suggest (fn [{:keys [v]}] (when (and (number? v) (\x3e\x3d (if (neg? v) (- v) v) 1000)) ["(compact)"]))\n   :refine [{:param :decimals :label "Decimals" :kind :choice :default 1 :options [[0 "0"] [1 "1"] [2 "2"]]}]}\n  ([] (compact 1))\n  ([decimals] (number-view {:notation "compact" :max-decimals decimals})))\n\n(defn ^:renderer file-size\n  "Renderer: a byte count in B, KB, MB, GB or TB (powers of 1024),\n  whichever reads best: 1536 → 1.5 KB. A cell whose unit is a data size\n  (B, kB, MB…) holds bytes already. Use as: file-size."\n  {:accepts #{:number} :aka "bytes KB MB GB storage"}\n  [v ctx]\n  (if (number? v)\n    (let [units ["B" "KB" "MB" "GB" "TB" "PB"]\n          i (loop [i 0 x (ABS v)] (if (and (\x3e\x3d x 1024) (\x3c i 5)) (recur (inc i) (/ x 1024)) i))]\n      [:span.num (format-number (/ v (POWER 1024 i)) {:max-decimals (if (zero? i) 0 1)})\n       " " (units i)])\n    (plain v ctx)))\n\n(defn ^:renderer duration\n  "Renderer: a span of time in days, hours, minutes and seconds — 75 s →\n  1m 15s, 3725 s → 1h 2m 5s, 90061 s → 1d 1h 1m 1s; fractions of a second\n  are dropped. In a cell with a time unit (s, min, h…) the value is that\n  time, whatever the unit; a plain number is a number of seconds. Use\n  as: duration."\n  {:accepts #{:number} :aka "time seconds minutes hours elapsed"}\n  [v ctx]\n  (if (number? v)\n    (let [secs (if (\x3d "time" (unit-kind (:unit ctx))) (in-unit v "s") v)\n          s (INT (ABS secs))\n          parts [[(quot s 86400) "d"] [(quot (mod s 86400) 3600) "h"]\n                 [(quot (mod s 3600) 60) "m"] [(mod s 60) "s"]]\n          shown (drop-while (comp zero? first) parts)]\n      [:span.num (when (neg? v) "−")\n       (if (seq shown)\n         (clojure.string/join " " (map (fn [[n u]] (str n u)) shown))\n         "0s")])\n    (plain v ctx)))\n\n(defn ^:renderer truncate\n  "Renderer maker: text cut to n characters with …, the whole value on\n  hover. (truncate 20). Numbers are shown whole, in the cell\'s format."\n  {:accepts #{:text} :aka "shorten ellipsis cut"\n   :suggest (fn [{:keys [v]}] (when (and (string? v) (\x3e (count v) 20)) ["(truncate 20)"]))\n   :refine [{:param :n :label "Characters" :kind :int :min 1 :max 200}]}\n  [n]\n  (fn [v ctx]\n    (let [s (cond (string? v) v\n                  (or (nil? v) (number? v) (boolean? v) (xl-error? v)) nil\n                  :else (pr-str v))]\n      (if (and s (\x3e (count s) n))\n        [:span.str {:title s} (str (subs s 0 (max 0 (dec n))) "…")]\n        (plain v ctx)))))\n\n(defn ^:renderer code\n  "Renderer: the value printed as Clojure data in a monospace font,\n  wrapping long lines. Use as: code."\n  {:accepts #{:seq :map :rows :table} :aka "edn data raw clojure"}\n  [v _]\n  [:code.r-code (pr-str v)])\n\n(defn ^:renderer html\n  "Renderer: the value is hiccup, drawn as-is — a formula returning\n  [:b \\"hi\\"] shows a bold hi. Values that aren\'t hiccup vectors are shown\n  plain. Use as: html."\n  {:accepts #{:hiccup} :aka "hiccup markup"}\n  [v ctx]\n  (if (and (vector? v) (keyword? (first v))) v (plain v ctx)))\n\n(defn ^:renderer markdown\n  "Renderer: text as Markdown, wrapped to the cell\'s width. # headings,\n  **bold**, *italic*, `code`, ~~struck~~, lists (- or 1.), \x3e quotes,\n  ``` code blocks, --- rules, | tables |, [links](https://…) and\n  ![images](…) (safe kinds of URL only, as for link). A line break in\n  the text is a line break. Links to cells: [[B6\x3eC9]] selects that cell,\n  and [[B6\x3eC9|these words]] shows your words. The target is read as a\n  formula in this cell reads references: B6\x3eC9 is C9 in the grid in B6 of\n  this grid, $\x3eB6\x3eC9 starts at the top grid, ..\x3eA1 is A1 in the grid\n  around this one; names and ranges work too. Anything but text is shown\n  plain. Use as: markdown."\n  {:accepts #{:text} :aka "rich text formatting bold headings"}\n  [v ctx]\n  (if (string? v)\n    (into [:div.r-md] (markdown-hiccup v ctx))\n    (plain v ctx)))\n\n(defn ^:renderer note\n  "Renderer: commentary, as Markdown (see markdown: **bold**, `code`,\n  lists, [[B6\x3eC9]] links to cells…) set close, for a column of notes beside\n  a table. A line break in the text is a line break. The guided tour\'s\n  notes use it, with a muted colour from their format rule. Use as: note."\n  {:accepts #{:text} :aka "comment annotation commentary"}\n  [v ctx]\n  (cond (string? v) (into [:div.r-md.r-note] (markdown-hiccup v ctx))\n        (some? v) (plain v ctx)\n        :else [:span]))\n\n(defn- link-href\n  "The href for a link or image made from string `s`, or nil if it isn\'t\n  one that\'s safe to follow: http(s) and mailto URLs, www. addresses\n  (given https), paths starting / ./ ../ or #, and (with `data-ok?`, for\n  images) data:image URLs."\n  [s data-ok?]\n  (when (string? s)\n    (cond (re-find #"(?i)^(https?://|mailto:)" s) s\n          (re-find #"(?i)^www\\." s) (str "https://" s)\n          (re-find #"^(/|\\./|\\.\\./|#)" s) s\n          (and data-ok? (re-find #"(?i)^data:image/" s)) s)))\n\n(defn ^:renderer link\n  "Renderer: a link that opens in a new tab. The value is a URL string,\n  [label url], or {:label .. :href ..}. Only http(s) and mailto URLs,\n  www. addresses and paths (/docs, #top) become links; anything else is\n  shown as text. Use as: link."\n  {:accepts #{:text} :aka "url hyperlink web"}\n  [v ctx]\n  (let [[label href] (cond (string? v) [v v]\n                           (map? v) [(or (:label v) (:href v)) (:href v)]\n                           (and (vector? v) (\x3d 2 (count v))) v\n                           :else [nil nil])]\n    (if-let [url (link-href href false)]\n      [:a.r-link {:href url :target "_blank" :rel "noopener noreferrer" :title url} (str label)]\n      (plain v ctx))))\n\n(defn ^:renderer image\n  "Renderer maker: the value is an image URL (http(s), a path such as\n  /img/logo.png, or data:image). (image) fits the image to the cell\'s width; (image 80)\n  makes it 80 pixels high."\n  {:accepts #{:text} :aka "picture photo logo url"\n   :suggest (fn [{:keys [v]}] (when (string? v) ["image"]))\n   :refine [{:param :height :label "Height (px)" :kind :int :min 10 :max 600}]}\n  ([] (image nil))\n  ([height]\n   (fn [v ctx]\n     (if-let [url (link-href v true)]\n       [:img.r-image {:src url :alt "" :style (when height {:height height :width "auto"})}]\n       (plain v ctx)))))\n\n(defn ^:renderer check\n  "Renderer: true (any value but false and nil) as ✓, false as ✗, nil\n  blank. Use as: check."\n  {:accepts #{:bool} :aka "tick boolean yes no true false"}\n  [v _]\n  (cond (nil? v) [:span]\n        v [:span.r-check.yes "✓"]\n        :else [:span.r-check.no "✗"]))\n\n(defn ^:renderer swatch\n  "Renderer: a CSS colour (\\"#e8743b\\", \\"teal\\", \\"rgb(0 128 0)\\") as a\n  small square of that colour, with its text. Use as: swatch."\n  {:accepts #{:text} :aka "colour color sample"}\n  [v ctx]\n  (if (and (string? v) (seq v))\n    [:span.r-swatch [:span.chip {:style {:background v}}] v]\n    (plain v ctx)))\n\n(defn text-on\n  "CSS colour for text drawn on the background `bg` (any CSS colour, a\n  var(--…) or a mix-color): black on light backgrounds, white on dark\n  ones, chosen by the browser from bg\'s lightness, so it follows the\n  theme. For renderers that paint a background:\n  {:background bg :color (text-on bg)}. A browser too old for relative\n  colours ignores it and keeps the usual text colour."\n  [bg]\n  (str "oklch(from " bg " clamp(0, (0.6 - l) * 1000, 1) 0 0 / 1)"))\n\n(defn ink\n  "CSS colour for what a renderer draws — a bar, an arc, a line: the\n  cell\'s text colour when its style sets one (the format bar, or a\n  column\'s or a conditional rule\'s style), else `default`, or the\n  theme\'s blue (var(--pos)) without one. So the cell\'s style chooses a\n  renderer\'s colour, cell by cell: [:rect {:style {:fill (ink)}}]. Text\n  doesn\'t need it: it takes the cell\'s colour anyway."\n  ([] (ink "var(--pos)"))\n  ([default] (str "var(--ink, " default ")")))\n\n(defn- value-hue\n  "A hue (0–359) picked from the value itself, so equal values get the\n  same colour."\n  [v]\n  (mod (hash (str v)) 360))\n\n(defn ^:renderer badge\n  "Renderer maker: the value as a coloured pill, for statuses and\n  categories. (badge) picks a colour from the value itself, so equal\n  values match; (badge {\\"done\\" \\"#cdeccd\\" \\"late\\" \\"#f6c6c0\\"}) uses yours\n  (values not in the map get the automatic colour)."\n  {:accepts #{:text} :aka "tag pill label status category"}\n  ([] (badge {}))\n  ([colors]\n   (fn [v ctx]\n     (if (nil? v)\n       [:span]\n       (let [bg (get colors v (str "hsl(" (value-hue v) " 65% 86%)"))]\n         [:span.r-badge {:style {:background bg :color (text-on bg)}}\n          (cond (string? v) v\n                (number? v) (number-text v ctx)\n                :else (pr-str v))])))))\n\n;;; # Renderers: combining\n;;; Renderer makers that wrap another renderer (`inner`, plain unless\n;;; given). Colours, bold and alignment are the cell\'s style, and red\n;;; negatives, hidden zeros and text around a number its number format\n;;; ("#,##0.00;[Red]-#,##0.00", "#,##0;-#,##0;", "\\"≈ \\"0.0"): these\n;;; choose or annotate the renderer itself.\n\n(defn ^:renderer render-if\n  "Renderer maker: draw the value with `then` when (pred value) holds,\n  otherwise with `else` (default plain): (render-if neg? (trend)),\n  (render-if string? link (data-bar 100)). A predicate that throws counts\n  as false. (To colour negatives red, give the cell a format such as\n  \\"#,##0.00;[Red]-#,##0.00\\", or a style rule {:when \\"neg?\\" :style …}.)"\n  ([pred then] (render-if pred then plain))\n  ([pred then else]\n   (fn [v ctx]\n     (if (try (pred v) (catch :default _ false)) (then v ctx) (else v ctx)))))\n\n(defn ^:renderer tooltip\n  "Renderer maker: text shown on hover. (tooltip \\"Net of tax\\") fixed\n  text; (tooltip f) shows (f value); a third argument is the inner\n  renderer: (tooltip \\"Net\\" (data-bar 100))."\n  ([text] (tooltip text plain))\n  ([text inner]\n   (fn [v ctx]\n     [:span {:title (str (if (fn? text) (text v) text))} (inner v ctx)])))\n\n;;; # Renderers: indicators\n;;; A value shown as a bar, colour, symbol or dial. Bounds are given as\n;;; lo and hi; values outside them are drawn at the nearest end. As in a\n;;; formula, a bound is in base units, or a quantity written as text, so\n;;; in a column of km (data-bar "50 km") is 0–50 km, and a bound read from\n;;; cells, (data-bar (MAX B2:B9)), is right whatever their unit. The\n;;; number drawn with the indicator is in the cell\'s format and unit.\n\n(defn- fraction\n  "Where x lies between lo and hi, as 0–1 (clamped); 0 when lo \x3d hi."\n  [x lo hi]\n  (if (\x3d lo hi) 0 (clamp (/ (- x lo) (- hi lo)) 0 1)))\n\n(defn mix-color\n  "CSS colour t of the way (0–1) from colour `from` to colour `to`, mixed\n  in sRGB: (mix-color \\"white\\" \\"red\\" 0.25). For renderers\' styles."\n  [from to t]\n  (str "color-mix(in srgb, " to " " (ROUND (* 100 (clamp t 0 1))) "%, " from ")"))\n\n(defn ^:renderer progress\n  "Renderer maker: a progress bar with the percentage. (progress) for\n  values 0–1, (progress hi) for 0–hi, (progress lo hi). Hover for the\n  value in the cell\'s format."\n  {:accepts #{:number} :aka "percent complete completion bar"\n   :suggest (fn [{:keys [v bounds]}]\n              (when (and (number? v) bounds)\n                (let [{:keys [lo hi hi-src]} bounds]\n                  (if (and (\x3e\x3d lo 0) (\x3c\x3d hi 1)) ["(progress)"] [(str "(progress " hi-src ")")]))))\n   :refine [{:param :hi :label "Full at" :kind :bound :end :hi :default 1}\n             {:param :lo :label "Empty at" :kind :bound :end :lo :default 0}]}\n  ([] (progress 0 1))\n  ([hi] (progress 0 hi))\n  ([lo hi]\n   (fn [v ctx]\n     (if (number? v)\n       (let [t (fraction v (option-number lo) (option-number hi))]\n         [:div.r-progress {:title (number-text v ctx)}\n          [:div.fill {:style {:width (str (* 100 t) "%")}}]\n          [:span.label (format-number t {:style "percent"})]])\n       (plain v ctx)))))\n\n(defn ^:renderer data-bar\n  "Renderer maker: the number over a bar as long as it is, like Excel\'s\n  data bars. (data-bar hi) for 0–hi, (data-bar lo hi); the number is in\n  the cell\'s format and unit, or drawn by `inner` if given: (data-bar 0\n  100 compact). Negative numbers get a red bar."\n  {:accepts #{:number} :compares true :aka "bar in cell databar conditional formatting"\n   :suggest (fn [{:keys [v bounds]}]\n              (when (and (number? v) bounds)\n                (let [{:keys [lo lo-src hi-src]} bounds]\n                  [(if (neg? lo) (str "(data-bar " lo-src " " hi-src ")") (str "(data-bar " hi-src ")"))])))\n   :refine [{:param :hi :label "Full at" :kind :bound :end :hi}\n             {:param :lo :label "Empty at" :kind :bound :end :lo :default 0}\n             {:param :inner :label "Number" :kind :renderer :default \'plain}]}\n  ([hi] (data-bar 0 hi))\n  ([lo hi] (data-bar lo hi plain))\n  ([lo hi inner]\n   (fn [v ctx]\n     (if (number? v)\n       [:div.r-data-bar\n        [:div.fill {:class (if (neg? v) "neg" "pos")\n                    :style {:width (str (* 100 (fraction (if (neg? v) (- v) v) (max 0 (option-number lo)) (option-number hi))) "%")}}]\n        [:div.label (inner v ctx)]]\n       (plain v ctx)))))\n\n(defn ^:renderer heat\n  "Renderer maker: fill the cell with a colour that deepens with the\n  value. (heat lo hi) from pale to the cell\'s text colour, or to blue\n  (darker in dark mode) without one; (heat lo hi from to) between two\n  CSS colours: (heat 0 100 \\"white\\" \\"tomato\\").\n  The value stays on top, in the cell\'s format (or drawn with `inner` if\n  given as a fifth argument), in black or white, whichever reads on the\n  colour (text-on): the fill is the point, so it covers the cell\'s own\n  background and text colour."\n  {:accepts #{:number} :compares true :aka "heatmap heat-map colour color scale conditional formatting"\n   :suggest (fn [{:keys [v bounds]}]\n              (when (and (number? v) bounds)\n                [(str "(heat " (:lo-src bounds) " " (:hi-src bounds) ")")]))\n   :refine [{:params [:from :to] :label "Colours" :kind :choice\n              :options [[nil "pale to the text colour"] [["white" "tomato"] "to red"] [["white" "seagreen"] "to green"]\n                        [["#fff5e6" "#e6550d"] "to orange"] [["seagreen" "tomato"] "green to red"]]}\n             {:param :hi :label "Deepest at" :kind :bound :end :hi}\n             {:param :lo :label "Palest at" :kind :bound :end :lo}]}\n  ([lo hi] (heat lo hi "var(--heat-lo)" (ink "var(--heat-hi)")))\n  ([lo hi from to] (heat lo hi from to plain))\n  ([lo hi from to inner]\n   (fn [v ctx]\n     (if (number? v)\n       (let [bg (mix-color from to (fraction v (option-number lo) (option-number hi)))]\n         [:div.r-fill {:style {:background bg :color (text-on bg)}} (inner v ctx)])\n       (plain v ctx)))))\n\n(defn ^:renderer trend\n  "Renderer maker: a change with an arrow — ▲ in green for a rise, ▼ in\n  red for a fall, ▬ for none — beside the number in the cell\'s format and\n  style: with \\"0.0%\\" (trend) shows ▲ 2.5%. (trend inner) draws the\n  number with another renderer: (trend compact)."\n  {:accepts #{:number} :aka "arrow change up down delta growth"\n   :refine [{:param :inner :label "Number" :kind :renderer :default \'plain}]}\n  ([] (trend plain))\n  ([inner]\n   (fn [v ctx]\n     (if (number? v)\n       (let [[cls arrow] (cond (pos? v) ["up" "▲"] (neg? v) ["down" "▼"] :else ["flat" "▬"])]\n         [:span.r-trend {:class cls} [:span.arrow arrow] (inner v ctx)])\n       (plain v ctx)))))\n\n(defn ^:renderer traffic-light\n  "Renderer maker: a coloured dot. (traffic-light lo hi): red below lo,\n  amber from lo to hi, green from hi up. When lower is better, give\n  lo \x3e hi: (traffic-light 10 5) is green up to 5 and red from 10. The value\n  shows beside the dot, in the cell\'s format; (traffic-light lo hi nil)\n  shows the dot alone."\n  {:accepts #{:number} :compares true :aka "status RAG red amber green signal indicator"\n   :suggest (fn [{:keys [v bounds num]}]\n              (when (and (number? v) bounds)\n                (let [{:keys [lo hi]} bounds d (/ (- hi lo) 3)]\n                  (when (pos? d)\n                    [(str "(traffic-light " (num (+ lo d)) " " (num (+ lo d d)) ")")]))))\n   :refine [{:param :lo :label "Amber from" :kind :number :fill 0}\n             {:param :hi :label "Green from" :kind :number :fill 1}\n             {:param :inner :label "Number" :kind :renderer :default \'plain}]}\n  ([lo hi] (traffic-light lo hi plain))\n  ([lo hi inner]\n   (fn [v ctx]\n     (if (number? v)\n       (let [lo (option-number lo) hi (option-number hi)\n             better (if (\x3c\x3d lo hi) v (- v))\n             [lo hi] (if (\x3c\x3d lo hi) [lo hi] [(- lo) (- hi)])\n             cls (cond (\x3c better lo) "red" (\x3c better hi) "amber" :else "green")]\n         [:span.r-light [:span.dot {:class cls :title (number-text v ctx)}] (when inner (inner v ctx))])\n       (plain v ctx)))))\n\n(defn ^:renderer stars\n  "Renderer maker: a rating as stars, rounded to the nearest half.\n  (stars) out of 5, (stars 10) out of 10."\n  {:accepts #{:number} :aka "rating score"\n   :suggest (fn [{:keys [v]}] (when (number? v) (cond (\x3c\x3d 0 v 5) ["stars"] (\x3c\x3d 0 v 10) ["(stars 10)"])))\n   :refine [{:param :out-of :label "Out of" :kind :choice :default 5 :options [[5 "5"] [10 "10"]]}]}\n  ([] (stars 5))\n  ([out-of]\n   (fn [v ctx]\n     (if (number? v)\n       (let [x (/ (ROUND (* 2 (clamp v 0 out-of))) 2)\n             full (INT x)\n             half? (not\x3d x full)]\n         [:span.r-stars {:title (str (number-text v (dissoc ctx :unit)) " / " out-of)}\n          (apply str (repeat full "★"))\n          (when half? [:span.half "★"])\n          [:span.off (apply str (repeat (- out-of full (if half? 1 0)) "★"))]])\n       (plain v ctx)))))\n\n(defn ^:renderer kpi\n  "Renderer maker: a big number with a caption under it, for dashboards,\n  in the cell\'s format and unit: (kpi \\"Revenue\\") with \\"[$€]#,##0\\"\n  shows €1,234,567; (kpi \\"Revenue\\" compact) shows €1.2M."\n  {:accepts #{:number} :showcase true :aka "big number headline metric figure dashboard"\n   :suggest (fn [{:keys [v label]}] (when (number? v) [(str "(kpi " (pr-str label) ")")]))\n   :refine [{:param :label :label "Caption" :kind :text}\n             {:param :inner :label "Number" :kind :renderer :default \'plain}]}\n  ([label] (kpi label plain))\n  ([label inner]\n   (fn [v ctx]\n     [:div.r-kpi [:div.big (inner v ctx)] [:div.caption label]])))\n\n(defn ^:renderer gauge\n  "Renderer maker: a half-dial filled to where the value lies between lo\n  and hi, with the value under it in the cell\'s format: (gauge 0 100),\n  (gauge 0 1) with \\"0%\\"."\n  {:accepts #{:number} :showcase true :aka "dial meter speedometer"\n   :suggest (fn [{:keys [v bounds]}]\n              (when (and (number? v) bounds)\n                [(str "(gauge " (if (neg? (:lo bounds)) (:lo-src bounds) "0") " " (:hi-src bounds) ")")]))\n   :refine [{:param :hi :label "Full at" :kind :bound :end :hi}\n             {:param :lo :label "Empty at" :kind :bound :end :lo}\n             {:param :inner :label "Number" :kind :renderer :default \'plain}]}\n  ([lo hi] (gauge lo hi plain))\n  ([lo hi inner]\n   (fn [v ctx]\n     (if (number? v)\n       (let [t (fraction v (option-number lo) (option-number hi))\n             a (* PI (- 1 t))\n             x (+ 50 (* 40 (COS a)))\n             y (- 48 (* 40 (SIN a)))]\n         [:div.r-gauge\n          [:svg {:viewBox "0 0 100 52"}\n           [:path.track {:d "M 10 48 A 40 40 0 0 1 90 48"}]\n           (when (pos? t)\n             [:path.value {:d (str "M 10 48 A 40 40 0 0 1 " x " " y)}])]\n          [:div.label (inner v ctx)]])\n       (plain v ctx)))))\n\n;;; # Renderers: collections\n;;; For values that hold several values: ranges (rows), sequences, maps\n;;; and grids\' value maps.\n\n(defn table-like?\n  "Whether v is a table: a non-empty sequence of maps (rows), as a grid\n  with headers gives (one map per row, keyed by the headers)."\n  [v]\n  (and (sequential? v) (seq v) (every? map? v)))\n\n(defn ^:renderer table\n  "Renderer: a 2-D value (a vector of rows) as a read-only table; a table\n  of row maps with a header row of its keys. Give a 2-D formula result\n  this renderer to keep it in its cell instead of spilling. Use as: table."\n  {:accepts #{:table :rows} :aka "grid rows columns"}\n  [v ctx]\n  (cond\n    (table-like? v)\n    (let [ks (distinct (mapcat keys v))]\n      [:table.value-table\n       (into [:tbody (into [:tr] (for [k ks] [:th (if (keyword? k) (name k) (str k))]))]\n             (for [row v]\n               (into [:tr] (for [k ks] [:td (plain (get row k) ctx)]))))])\n    (sequential? v)\n    [:table.value-table\n     (into [:tbody]\n           (for [row v]\n             (into [:tr] (for [x (if (sequential? row) row [row])]\n                           [:td (plain x ctx)]))))]\n    :else (plain v ctx)))\n\n(defn ^:renderer size\n  "Renderer: a range or other 2-D value as its size, \\"3×2 range\\",\n  keeping it in its cell instead of spilling (an imported workbook\'s\n  named ranges are shown this way); anything else plain. Use as: size."\n  {:accepts #{:rows} :aka "dimensions rows columns count"}\n  [v ctx]\n  (if (and (sequential? v) (seq v) (every? sequential? v))\n    [:span.code (str (count v) "×" (reduce max 0 (map count v)) " range")]\n    (plain v ctx)))\n\n(defn ^:renderer table-of\n  "Renderer maker: like table, with each value drawn by `inner`:\n  (table-of check), (table-of (data-bar 100)). (table already shows\n  numbers in the cell\'s format and unit.)"\n  {:accepts #{:rows :table} :aka "table with bars inner"\n   :suggest (fn [{:keys [v nice num]}]\n              (let [xs (filter number? (flatten (map #(if (map? %) (vals %) %) v)))\n                    hi (reduce max 0 (map #(if (neg? %) (- %) %) xs))]\n                (when (pos? hi) [(str "(table-of (data-bar " (num (nice hi)) "))")])))\n   :refine [{:param :inner :label "Each value" :kind :renderer}]}\n  [inner]\n  (fn [v ctx]\n    (if (sequential? v)\n      [:table.value-table\n       (into [:tbody]\n             (for [row v]\n               (into [:tr] (for [x (if (sequential? row) row [row])]\n                             [:td (inner x ctx)]))))]\n      (inner v ctx))))\n\n(defn ^:renderer heatmap\n  "Renderer: a 2-D range of numbers as a table, each number on a colour\n  between the smallest (pale) and the largest (the cell\'s text colour,\n  or blue without one). Use as: heatmap."\n  {:accepts #{:rows} :aka "matrix heat map colour color grid"}\n  [v ctx]\n  (let [ns (nums v)\n        lo (if (seq ns) (apply min ns) 0)\n        hi (if (seq ns) (apply max ns) 0)]\n    (if-not (sequential? v)\n      (plain v ctx)\n      [:table.value-table.r-heatmap\n       (into [:tbody]\n          (for [row v]\n            (into [:tr] (for [x (if (sequential? row) row [row])]\n                          [:td {:style (when (number? x)\n                                         (let [bg (mix-color "var(--heat-lo)" (ink "var(--heat-hi)") (fraction x lo hi))]\n                                           {:background bg :color (text-on bg)}))}\n                           (plain x ctx)]))))])))\n\n(defn ^:renderer bullets\n  "Renderer: the values in a sequence, range or map as a bulleted list\n  (empty cells skipped). Use as: bullets."\n  {:accepts #{:seq :map :rows} :aka "list items"}\n  [v ctx]\n  (into [:ul.r-list] (for [x (cells v)] [:li (plain x ctx)])))\n\n(defn ^:renderer numbered\n  "Renderer: like bullets, as a numbered list. Use as: numbered."\n  {:accepts #{:seq :map :rows} :aka "ordered list items"}\n  [v ctx]\n  (into [:ol.r-list] (for [x (cells v)] [:li (plain x ctx)])))\n\n(defn ^:renderer key-values\n  "Renderer: a map — a grid\'s values, or any record — as a table of keys\n  and values; nested maps become nested tables. A grid\'s values (a grid\n  cell\'s, or what call returns) show as its named cells, each labelled\n  by the text to its left (else its name) and shown in its own format\n  and unit; a grid without names shows its values laid out as in the\n  grid. Use as: key-values."\n  {:accepts #{:map :grid} :aka "record properties fields"}\n  [v ctx]\n  (let [f (:grid-cells ctx)\n        named (when f (:cells (f v {:named? true})))\n        cells (when (and f (empty? named)) (:cells (f v)))\n        show (fn [{:keys [value format unit]}]\n               (if (map? value)\n                 (key-values value ctx)\n                 ;; the cell\'s own format, else the one this renderer\'s cell has\n                 (plain value (assoc ctx :format (or format (:format ctx)) :unit (or unit (:unit ctx))))))]\n    (cond\n      (seq named)\n      [:table.value-table.r-kv\n       (into [:tbody]\n             (for [c named]\n               [:tr [:th {:title (:name c)} (or (:label c) (:name c))] [:td (show c)]]))]\n\n      (seq cells)\n      (let [rows (sort (distinct (map (comp first :pos) cells)))\n            cols (sort (distinct (map (comp second :pos) cells)))\n            at (into {} (map (juxt :pos identity)) cells)]\n        [:table.value-table.r-kv-grid\n         (into [:tbody]\n               (for [r rows]\n                 (into [:tr] (for [c cols]\n                               [:td (some-\x3e (at [r c]) show)]))))])\n\n      (map? v)\n      [:table.value-table.r-kv\n       (into [:tbody]\n             (for [[k x] v]\n               [:tr [:th (if (keyword? k) (name k) (str k))]\n                [:td (if (map? x) (key-values x ctx) (plain x ctx))]]))]\n\n      :else (plain v ctx))))\n\n;;; # Renderers: charts\n;;; Small SVG charts that fill the cell\'s width. Widen the column (or set\n;;; the row\'s height) to make them bigger.\n\n(def chart-colors\n  "The colours pie and donut give their slices, in order. To use others,\n  pass them: (pie [\\"#1b7f4b\\" \\"#79c28f\\" …]). (Redefining chart-colors in\n  a grid\'s library doesn\'t recolour the standard charts: like every\n  standard function, they use the standard definition.)"\n  ["#4e79a7" "#f28e2b" "#59a14f" "#e15759" "#76b7b2" "#edc948" "#b07aa1" "#ff9da7" "#9c755f" "#bab0ac"])\n\n(defn ^:renderer bars\n  "Renderer: a column chart of the numbers in the value (a range, a\n  sequence, a grid); negative numbers hang below the axis. Hover a column\n  for its number, in the cell\'s format and unit. Use as: bars."\n  {:accepts #{:seq :map :rows} :aka "column chart mini bar graph"}\n  [v ctx]\n  (let [ns (nums v)\n        n  (count ns)]\n    (if (zero? n)\n      [:span.muted "no data"]\n      (let [hi (max 0 (apply max ns)) lo (min 0 (apply min ns))\n            span (if (\x3d hi lo) 1 (- hi lo))\n            w 100 h 40 bw (/ w n)\n            y (fn [x] (* h (/ (- hi x) span)))]\n        (into [:svg.chart {:viewBox (str "0 0 " w " " h) :preserveAspectRatio "none"}]\n              (map-indexed\n                (fn [i x]\n                  [:rect {:x (+ (* i bw) (* 0.1 bw)) :width (* 0.8 bw)\n                          :y (min (y x) (y 0)) :height (max 0.5 (ABS (- (y x) (y 0))))\n                          :class (if (neg? x) "neg" "pos")}\n                   [:title (short-number x ctx)]])\n                ns))))))\n\n(defn ^:renderer sparkline\n  "Renderer: a line chart of the numbers in the value, scaled to fit.\n  Needs two numbers or more. Use as: sparkline."\n  {:accepts #{:seq :map :rows} :aka "line trend mini chart graph"}\n  [v _]\n  (let [ns (nums v) n (count ns)]\n    (if (\x3c n 2)\n      [:span.muted "need 2+ numbers"]\n      (let [hi (apply max ns) lo (apply min ns) span (if (\x3d hi lo) 1 (- hi lo))\n            w 100 h 40\n            pts (map-indexed (fn [i x] (str (* w (/ i (dec n))) "," (* h (/ (- hi x) span)))) ns)]\n        [:svg.chart {:viewBox (str "0 0 " w " " h) :preserveAspectRatio "none"}\n         [:polyline {:points (clojure.string/join " " pts) :class "line"}]]))))\n\n(defn- labelled-numbers\n  "[label number] pairs from a map {label n} (a grid\'s values), rows of\n  [label n] such as a two-column range (empty rows skipped), or plain\n  numbers (labelled by position). Non-numbers are left out."\n  [v]\n  (let [rows (when (and (sequential? v) (every? sequential? v))\n               (remove #(every? nil? %) v))]\n    (cond\n      (map? v) (for [[k x] v :when (number? x)] [(if (keyword? k) (name k) (str k)) x])\n      (and (seq rows) (every? #(and (\x3d 2 (count %)) (not (number? (first %))) (number? (second %))) rows))\n      (for [[k x] rows] [(if (keyword? k) (name k) (str k)) x])\n      :else (map-indexed (fn [i x] [(str (inc i)) x]) (nums v)))))\n\n(defn ^:renderer bar-list\n  "Renderer: labelled horizontal bars, the longest for the biggest number.\n  The value is a map {label number} (a grid\'s values work), rows of\n  [label number] (a two-column range), or just numbers. The numbers are\n  in the cell\'s format and unit (three significant digits without a\n  format). Use as: bar-list."\n  {:accepts #{:seq :map :rows} :aka "horizontal bar chart ranking graph"}\n  [v ctx]\n  (let [rows (labelled-numbers v)\n        hi (reduce max 0 (map (comp ABS second) rows))]\n    (if (empty? rows)\n      [:span.muted "no data"]\n      (into [:div.r-bar-list]\n            (for [[label x] rows]\n              [:div.row\n               [:span.label {:title label} label]\n               [:span.track [:span.fill {:class (if (neg? x) "neg" "pos")\n                                         :style {:width (str (if (zero? hi) 0 (* 100 (/ (ABS x) hi))) "%")}}]]\n               [:span.num (short-number x ctx)]])))))\n\n(defn- slices\n  "SVG paths for a pie of the positive numbers in `rows` ([label n]\n  pairs), radius r, centred on (50, 50), each with a hover title (the\n  number as ctx\'s cell shows it), coloured from `colors` in turn."\n  [rows r colors ctx]\n  (let [rows (filter (comp pos? second) rows)\n        total (reduce + 0 (map second rows))\n        pt (fn [t] [(+ 50 (* r (SIN (* 2 PI t)))) (- 50 (* r (COS (* 2 PI t))))])]\n    (if (\x3d 1 (count rows))\n      [[:circle {:cx 50 :cy 50 :r r :fill (first colors)} [:title (ffirst rows)]]]\n      (loop [acc [] t 0 [[label x] \x26 more] rows i 0]\n        (if (nil? x)\n          acc\n          (let [t\' (+ t (/ x total))\n                [x0 y0] (pt t) [x1 y1] (pt t\')]\n            (recur (conj acc [:path {:d (str "M 50 50 L " x0 " " y0 " A " r " " r " 0 "\n                                             (if (\x3e (- t\' t) 0.5) 1 0) " 1 " x1 " " y1 " Z")\n                                     :fill (nth colors (mod i (count colors)))}\n                              [:title (str label ": " (short-number x ctx) " (" (format-number (/ x total) {:style "percent"}) ")")]])\n                   t\' more (inc i))))))))\n\n(defn- draw-pie\n  "A pie of value `v` in `colors`, with the total in a hole if `hole?`:\n  in the cell\'s format if it has one, else in short form (12.3K), in its\n  unit."\n  [v ctx colors hole?]\n  (let [rows (labelled-numbers v)\n        colors (if (seq colors) (vec colors) chart-colors)\n        total (reduce + 0 (filter pos? (map second rows)))]\n    (if (pos? total)\n      (cond-\x3e (into [:svg.r-pie {:viewBox "0 0 100 100"}] (slices rows 48 colors ctx))\n        hole? (conj [:circle.hole {:cx 50 :cy 50 :r 28}]\n                    [:text {:x 50 :y 50 :text-anchor "middle" :dominant-baseline "central"}\n                     (if (:format ctx)\n                       (number-text total ctx)\n                       (unit-text (format-number (shown-number total ctx) {:notation "compact" :max-decimals 1})\n                                  (:unit ctx)))]))\n      [:span.muted "no data"])))\n\n(defn ^:renderer pie\n  "Renderer: a pie chart of the positive numbers in the value — a map\n  {label number}, rows of [label number], or plain numbers. Hover a\n  slice for its label, value and share. Use as: pie, or (pie colors) with\n  a vector of CSS colours for the slices (default chart-colors)."\n  {:accepts #{:seq :map :rows} :aka "pie chart share parts graph"\n   :refine [{:param :colors :label "Colours" :kind :choice\n              :options [[nil "chart colours"] [["#08519c" "#3182bd" "#6baed6" "#bdd7e7" "#eff3ff"] "blues"]\n                        [["#1b7f4b" "#41ab5d" "#79c28f" "#a1d99b" "#e5f5e0"] "greens"]\n                        [["#b30000" "#e34a33" "#fc8d59" "#fdbb84" "#fef0d9"] "warm"]]}]}\n  ([colors] (fn [v ctx] (draw-pie v ctx colors false)))\n  ([v ctx] (draw-pie v ctx chart-colors false)))\n\n(defn ^:renderer donut\n  "Renderer: like pie, with a hole showing the total. Use as: donut, or\n  (donut colors)."\n  {:accepts #{:seq :map :rows} :aka "doughnut ring chart share graph"\n   :refine [{:param :colors :label "Colours" :kind :choice\n              :options [[nil "chart colours"] [["#08519c" "#3182bd" "#6baed6" "#bdd7e7" "#eff3ff"] "blues"]\n                        [["#1b7f4b" "#41ab5d" "#79c28f" "#a1d99b" "#e5f5e0"] "greens"]\n                        [["#b30000" "#e34a33" "#fc8d59" "#fdbb84" "#fef0d9"] "warm"]]}]}\n  ([colors] (fn [v ctx] (draw-pie v ctx colors true)))\n  ([v ctx] (draw-pie v ctx chart-colors true)))\n\n;;; # Renderers: Vega-Lite charts\n;;; Charts with axes, legends and tooltips, drawn by Vega-Lite\n;;; (vega.github.io/vega-lite): give a spec in its JSON shape as a Clojure\n;;; map, and the cell\'s value is its data. (vega-lite {:mark :bar\n;;; :encoding {:x {:field :region :type :nominal} :y {:field :qty\n;;; :aggregate :sum :type :quantitative}}}) over a table draws total qty by\n;;; region. chart is a shorter way for the common cases. A chart is as tall\n;;; as its row\'s set height (180px otherwise) and as wide as its column; a\n;;; span (cell menu → Span) or a panel\'s :spans gives it more room. It\n;;; takes the app\'s colours, light or dark. Charts draw from the sheet only:\n;;; a spec\'s data.url isn\'t fetched.\n\n(defn- vl-key\n  "A column name from a header: lower case, spaces as -, as tables key\n  their rows."\n  [h]\n  (keyword (clojure.string/replace (clojure.string/lower-case (clojure.string/trim (str h))) #"\\s+" "-")))\n\n(defn- vl-label\n  "A key as text: a keyword\'s name."\n  [k]\n  (if (keyword? k) (name k) (str k)))\n\n(defn vl-rows\n  "A value as Vega-Lite data, a vector of row maps: a table (row maps) as\n  it is; a map {label number} — a grid\'s values, a group\'s totals — as\n  rows {:key label :value number}; rows with a header row of text keyed\n  by the headers; a list of values as {:index 1.. :value x}; anything\n  else as one row {:value x}."\n  [v]\n  (cond\n    (and (sequential? v) (seq v) (every? map? v)) (vec v)\n    (map? v) (mapv (fn [[k x]] {:key (vl-label k) :value x}) v)\n    (and (sequential? v) (next v) (every? sequential? v) (every? string? (first v)))\n    (let [ks (mapv vl-key (first v))]\n      (mapv #(zipmap ks %) (rest v)))\n    (and (sequential? v) (every? sequential? v))\n    (vec (map-indexed (fn [i x] {:index (inc i) :value x}) (mapcat identity v)))\n    (sequential? v) (vec (map-indexed (fn [i x] {:index (inc i) :value x}) v))\n    (nil? v) []\n    :else [{:value v}]))\n\n(defn- temporal-fields\n  "The fields a spec\'s encodings read as dates or times."\n  [spec]\n  (set (for [[_ e] (:encoding spec)\n             :when (and (map? e) (#{:temporal "temporal"} (:type e)) (:field e))]\n         (keyword (vl-label (:field e))))))\n\n(defn- serial-\x3ems\n  "A date as a number (days since 30 December 1899, Excel\'s) as\n  milliseconds since 1970, which Vega reads as a date (UTC)."\n  [x]\n  (* (- x 25569) 86400000))\n\n(defn vega-spec\n  "Vega-Lite spec `spec` with value `v` as its data (unless it has data of\n  its own): vl-rows, with fields used as :temporal turned from date\n  numbers into dates."\n  [spec v]\n  (if (:data spec)\n    spec\n    (let [tf (temporal-fields spec)\n          rows (cond-\x3e\x3e (vl-rows v)\n                 (seq tf) (mapv (fn [row] (reduce (fn [row k] (let [x (get row k)]\n                                                                (if (number? x) (assoc row k (serial-\x3ems x)) row)))\n                                                  row tf))))]\n      (cond-\x3e (assoc spec :data {:values rows})\n        ;; dates are read as UTC, so draw them in UTC too (no time-zone shift)\n        (seq tf) (update :encoding\n                         (fn [enc] (into {} (map (fn [[ch e]]\n                                                   [ch (if (and (map? e) (#{:temporal "temporal"} (:type e)) (not (:scale e)))\n                                                         (assoc e :scale {:type :utc})\n                                                         e)]))\n                                         enc)))))))\n\n(defn ^:renderer vega-lite\n  "Renderer maker: a Vega-Lite chart, spec `spec` (Vega-Lite\'s JSON shape\n  as a Clojure map; keywords become strings), drawing the cell\'s value\n  (see vl-rows) unless the spec has :data. (vega-lite {:mark :line\n  :encoding {:x {:field :date :type :temporal} :y {:field :qty :type\n  :quantitative}}}). Date numbers in a :temporal field are read as dates."\n  [spec]\n  (fn [v ctx]\n    (if-let [f (:vega-lite ctx)]\n      (f (vega-spec spec v))\n      [:span.muted "a Vega-Lite chart"])))\n\n(defn- deep-merge\n  "b merged into a, maps within maps merged too."\n  [a b]\n  (if (and (map? a) (map? b)) (merge-with deep-merge a b) b))\n\n(defn- field-type\n  "Vega-Lite\'s type for field k in rows: quantitative for numbers,\n  nominal otherwise."\n  [rows k]\n  (let [xs (remove nil? (map #(get % k) rows))]\n    (if (and (seq xs) (every? number? xs)) :quantitative :nominal)))\n\n(def ^:private few-categories\n  "At most this many values across make a pie, or a colour per value, in\n  what chart-suggestions offers."\n  8)\n\n(defn chart-suggestions\n  "The (chart …) calls worth offering for value v, as text: what the\n  Renderer field\'s gallery offers chart as, and what the Shelf tab offers\n  a selection as one chart. Over columns (a table, or a range under a row of\n  headings, keyed as vl-rows keys it), the first column that isn\'t\n  numbers across and the first that is up, as columns, a line and, for a\n  few positive parts, a pie; coloured by a second text column of few\n  values; two number columns as a scatter. A map {label number} as\n  columns and a pie, a list of numbers as a line and columns. Categories\n  not already in order keep the rows\' ({:x {:sort nil}}): Vega-Lite\n  would sort them."\n  [v]\n  (let [rows (cond (and (sequential? v) (seq v) (every? map? v)) (vec v)\n                   (and (sequential? v) (next v) (every? sequential? v) (every? string? (first v)))\n                   (let [ks (mapv vl-key (first v))] (mapv #(zipmap ks %) (rest v))))\n        mk (fn [mark x y opts]\n             (str "(chart " mark " " (pr-str x) " " (pr-str y)\n                  (when (seq opts) (str " " (clojure.string/replace (pr-str opts) ", " " "))) ")"))]\n    (if rows\n      (let [ks (distinct (mapcat keys rows))\n            col (fn [k] (map #(get % k) rows))\n            num-col? (fn [k] (let [xs (remove nil? (col k))] (and (seq xs) (every? number? xs))))\n            nums (filter num-col? ks)\n            cats (remove num-col? ks)\n            [x c2] cats\n            [y y2] nums\n            distinct-n (fn [k] (count (distinct (col k))))\n            in-order? (fn [k] (let [xs (col k)] (try (\x3d xs (sort xs)) (catch :default _ false))))\n            keep-order (when (and x (not (in-order? x))) {:x {:sort nil}})\n            parts? (and x y (\x3c\x3d (distinct-n x) few-categories)\n                        (every? #(or (nil? %) (\x3e\x3d % 0)) (col y)))]\n        (cond\n          (and x y)\n          (cond-\x3e [(mk :bar x y keep-order) (mk :line x y keep-order)]\n            ;; a pie\'s legend sorts too\n            parts? (conj (mk :arc x y (when keep-order {:color {:sort nil}})))\n            (and c2 (\x3c\x3d 2 (distinct-n c2) few-categories)) (conj (mk :bar x y (assoc keep-order :color c2))))\n          (and y y2) [(mk :point y y2 nil)]))\n      (cond\n        (and (map? v) (seq v) (every? number? (vals v)))\n        ["(chart :bar)" "(chart :arc)"]\n        (and (sequential? v) (next v) (every? number? v))\n        ["(chart :line :index :value)" "(chart :bar :index :value)"]))))\n\n;; chart\'s refinement is too varied for parameter specs: it has a refiner\n;; of its own, as any renderer can (see Writing a refiner, under Renderers).\n\n(defn- dissoc-path\n  "`m` without the value at `path`, dropping maps that it empties."\n  [m path]\n  (if (next path)\n    (let [inner (dissoc-path (get m (first path)) (rest path))]\n      (if (seq inner) (assoc m (first path) inner) (dissoc m (first path))))\n    (dissoc m (first path))))\n\n(defn chart-refine\n  "The refiner of chart, for the Renderer field\'s refine mode: rows of\n  variations on `call`, (chart mark x y opts), drawn with the value in\n  (:value info). The kind of chart, its columns, the summary, colour,\n  order, and a few touches (dates across, points on a line, a zero\n  baseline, a title). Each row is a map with :label and either :choices\n  [{:caption :form}] (drawn as tiles) or a control, :select {:value\n  :options [[v caption]]}, :text {:value}, :number {:value :min :max\n  :step} or :toggle {:value}, with :set, a function of the control\'s new\n  value giving the new call. A row of :choices with :named? true is\n  offered by name rather than drawn (variations drawn alike are anyway)."\n  [call info]\n  (let [[_ mark x y opts] (if (seq? call) call (list call))\n        mark (or mark :bar) x (or x :key) y (or y :value) opts (or opts {})\n        mk (fn [m x y o] (if (seq o) (list \'chart m x y o) (list \'chart m x y)))\n        at (fn [path v] (mk mark x y (if (nil? v) (dissoc-path opts path) (assoc-in opts path v))))\n        rows (vl-rows (:value info))\n        ks (distinct (mapcat keys rows))\n        nums (filter #(\x3d :quantitative (field-type rows %)) ks)\n        cats (remove (set nums) ks)\n        summed? (contains? #{:bar :arc} mark)\n        summary (if (contains? opts :aggregate) (:aggregate opts) (when summed? :sum))]\n    (cond-\x3e\n      [{:label "Kind"\n        :choices (for [[m o cap] [[:bar nil "columns"] [:line nil "line"] [:area nil "area"]\n                                  [:point nil "points"] [:arc nil "pie"] [:arc {:innerRadius 40} "donut"]]]\n                   {:caption cap\n                    :form (mk m x y (if o (assoc opts :mark o) (dissoc opts :mark)))})}\n       {:label "Across" :select {:value x :options (for [k ks] [k (name k)])} :set #(mk mark % y opts)}\n       {:label "Up" :select {:value y :options (for [k nums] [k (name k)])} :set #(mk mark x % opts)}\n       {:label "Summary"\n        :select {:value summary :options [[:sum "sum"] [:mean "average"] [:count "count"] [:max "largest"] [nil "none"]]}\n        :set (fn [v] (mk mark x y (if (\x3d v (when summed? :sum)) (dissoc opts :aggregate) (assoc opts :aggregate v))))}\n       {:label "Colour by"\n        :select {:value (:color opts) :options (cons [nil "none"] (for [k cats :when (not\x3d k x)] [k (name k)]))}\n        :set #(at [:color] %)}]\n      (not\x3d mark :arc)\n      (conj {:label "Order"\n             :choices [{:caption "as in the rows" :form (mk mark x y (assoc-in opts [:x :sort] nil))}\n                       {:caption "largest first" :form (at [:x :sort] "-y")}\n                       {:caption "a to z" :form (at [:x :sort] nil)}]}\n            {:label "Dates across" :toggle {:value (\x3d :temporal (get-in opts [:x :type]))}\n             :set #(at [:x :type] (when % :temporal))}\n            {:label "Start at zero" :toggle {:value (not (false? (get-in opts [:y :scale :zero])))}\n             :set #(at [:y :scale :zero] (when-not % false))})\n      (\x3d mark :line)\n      (conj {:label "Points on the line" :toggle {:value (true? (get-in opts [:mark :point]))}\n             :set #(at [:mark :point] (when % true))})\n      true\n      (conj {:label "Title" :text {:value (:title opts)} :set #(at [:title] (when (seq %) %))}))))\n\n(defn ^:renderer chart\n  "Renderer maker: a Vega-Lite chart of the cell\'s value with `mark`\n  (:bar :line :point :area :arc :tick …), field x across and y up, typed\n  from the data (numbers are quantities, the rest categories). Without\n  fields, :key and :value: (chart :bar) over a map {label number}, a\n  group\'s totals. (chart :bar :region :qty) sums qty by region (a bar or\n  arc sums; give :aggregate nil for none). `opts` is merged into the spec:\n  {:color :month} colours by a field; {:x {:type :temporal}} reads x as\n  dates; {:title \\"Sales\\"}, or any other Vega-Lite setting. :arc (a pie)\n  takes x as the category and y as the size."\n  {:accepts #{:table :map :rows :seq} :aka "graph plot vega line bar scatter area"\n   :suggest (fn [{:keys [v]}] (chart-suggestions v))\n   :refine chart-refine}\n  ([mark] (chart mark :key :value {}))\n  ([mark x y] (chart mark x y {}))\n  ([mark x y opts]\n   (fn [v ctx]\n     (let [rows (vl-rows v)\n           arc? (#{:arc "arc"} mark)\n           agg (if (contains? opts :aggregate) (:aggregate opts) (when (#{:bar :arc "bar" "arc"} mark) :sum))\n           yt (field-type rows y)\n           ;; a map\'s :key and :value say nothing as titles\n           yenc (cond-\x3e {:field y :type yt}\n                  (and agg (\x3d yt :quantitative)) (assoc :aggregate agg)\n                  (\x3d y :value) (assoc :title nil))\n           xenc (cond-\x3e {:field x :type (field-type rows x)} (\x3d x :key) (assoc :title nil))\n           color (when-not (map? (:color opts)) (:color opts))\n           enc (if arc?\n                 {:theta yenc :color xenc}\n                 (cond-\x3e {:x xenc :y yenc}\n                   color (assoc :color {:field color :type (field-type rows color)})))\n           base {:mark (if (keyword? mark) {:type mark :tooltip true} mark) :encoding enc}\n           spec (deep-merge base {:encoding (cond-\x3e (select-keys opts [:x :y :theta])\n                                              (map? (:color opts)) (assoc :color (:color opts)))})\n           spec (deep-merge spec (dissoc opts :x :y :color :theta :aggregate))]\n       ((vega-lite spec) v ctx)))))\n\n;;; # Renderers: interactive\n;;; Controls that write into cells: most edit their own cell\'s value, so\n;;; formulas elsewhere can read it. Put the control in an input cell and\n;;; refer to it. A control\'s reading is in the cell\'s format and unit; in\n;;; a cell with a unit its numbers are quantities, so bounds and steps are\n;;; in base units or written as text: (slider "0 km" "20 km" "0.5 km").\n;;; What a control writes keeps the cell\'s unit.\n\n;; button\'s refinement: what a click does, and to which cell, read back\n;; from the handler when it\'s one the refiner wrote.\n\n(def ^:private button-actions\n  "What button-refine offers a click to do: [caption (fn [target]\n  handler-body)]."\n  [["add 1" (fn [t] (list \'update-cell! \'ctx (list \'quote t) \'inc))]\n   ["take 1" (fn [t] (list \'update-cell! \'ctx (list \'quote t) \'dec))]\n   ["set to 0" (fn [t] (list \'set-cell! \'ctx (list \'quote t) 0))]\n   ["set to today" (fn [t] (list \'set-cell! \'ctx (list \'quote t) \'(TODAY)))]\n   ["switch on and off" (fn [t] (list \'update-cell! \'ctx (list \'quote t) \'not))]])\n\n(defn button-refine\n  "The refiner of button, for the Renderer field\'s refine mode: what a\n  click does (add 1, take 1, set to 0, set to today, switch on and off)\n  and the cell it changes (beside it, or one named), when the handler is\n  (fn [ctx] (update-cell! ctx \'r1 inc)) or (fn [ctx] (set-cell! ctx \'r1\n  0)) and the like. Another handler is kept, and can be replaced."\n  [call info]\n  (let [[_ handler] (if (seq? call) call (list call))\n        body (when (and (seq? handler) (\x3d \'fn (first handler))) (last handler))\n        target (let [q (when (seq? body) (nth body 2 nil))]\n                 (if (and (seq? q) (\x3d \'quote (first q))) (second q) \'r1))\n        action (some (fn [[cap f]] (when (\x3d body (f target)) cap)) button-actions)\n        mk (fn [b] (list \'button (list \'fn \'[ctx] b)))\n        with-target (fn [t] (mk ((or (some (fn [[cap f]] (when (\x3d cap action) f)) button-actions)\n                                     (second (first button-actions)))\n                                 t)))]\n    [{:label "When clicked"\n      ;; buttons look the same whatever they do: by name\n      :named? true\n      :choices (for [[cap f] button-actions] {:caption cap :form (mk (f target))})}\n     {:label "Cell it changes"\n      :select {:value target :options [[\'r1 "the one to its right"] [\'l1 "to its left"]\n                                       [\'d1 "below"] [\'u1 "above"]]}\n      :set with-target}\n     {:label "Or a cell named" :text {:value (when-not (#{\'r1 \'l1 \'d1 \'u1} target) (str target))}\n      :set (fn [s] (when (seq s) (with-target (symbol s))))}]))\n\n(defn ^:renderer button\n  "Renderer maker: a button labelled with the cell\'s value (a number in\n  its format); (on-click ctx) runs on click. (button (fn [ctx] (set-cell!\n  ctx \'r1 0)))."\n  {:accepts #{:text :number} :aka "action click press"\n   ;; a button labelled with the cell\'s value, changing the cell beside it\n   :suggest (fn [{:keys [v]}] (when (some? v) ["(button (fn [ctx] (update-cell! ctx \'r1 inc)))"]))\n   :refine button-refine}\n  [on-click]\n  (fn [v ctx]\n    [:button.cell-button {:on-click (fn [_] (on-click ctx))}\n     (if (number? v) (number-text v ctx) (str v))]))\n\n(defn ^:renderer counter-button\n  "Renderer maker: a button that adds `step` to the number in the cell at\n  `ref`: (counter-button \'r1 1)."\n  {:accepts #{:text} :aka "count increment tally clicker"\n   :suggest (fn [{:keys [v]}] (when (string? v) ["(counter-button \'r1 1)"]))\n   :refine [{:param :ref :label "Adds to" :kind :choice\n            :options [[\'\'r1 "the cell to its right"] [\'\'l1 "to its left"] [\'\'d1 "below"] [\'\'u1 "above"]]}\n           {:param :step :label "Step" :kind :number :fill 1 :placeholder "1 (or -1, 5, 10)"}]}\n  [ref step]\n  (button (fn [ctx] (update-cell! ctx ref #(+ (or % 0) step)))))\n\n(defn ^:renderer slider\n  "Renderer maker: a slider editing this cell\'s own number, with its\n  reading in the cell\'s format and unit: (slider 0 10), (slider 0 1\n  0.05), (slider \\"0 km\\" \\"20 km\\" \\"0.5 km\\"). Without a step it steps by\n  1 of the cell\'s unit (1 km in a km cell). (slider) takes its bounds and\n  step from the cell\'s validation, e.g. (between 0 10), else 0–100."\n  {:accepts #{:number :empty} :writes-own true :aka "range input drag"\n   :suggest (fn [{:keys [v constraint nice num]}]\n              (cond (or (:min constraint) (:max constraint)) ["slider"]\n                    (number? v) [(str "(slider 0 " (num (if (pos? v) (nice (* 2 v)) 10)) ")")]))\n   :refine [{:param :lo :label "From" :kind :number :fill 0}\n             {:param :hi :label "To" :kind :number :fill 100}\n             {:param :step :label "Step" :kind :number :min 0 :placeholder "1 (or 0.5, 0.1, 0.01)"}]}\n  ([] (fn [v ctx]\n        (let [{:keys [min max step]} (:constraint ctx)]\n          ((slider (or min 0) (or max 100) step) v ctx))))\n  ([lo hi] (slider lo hi nil))\n  ([lo hi step]\n   (let [lo (option-number lo) hi (option-number hi) step (option-number step)]\n     (fn [v ctx]\n       [:span.slider\n        [:input {:type "range" :min lo :max hi :step (or step (unit-step ctx)) :value (if (number? v) v lo)\n                 :on-change (fn [e] (set-self! ctx (str-\x3enum (event-value e))))}]\n        (plain v ctx)]))))\n\n(defn ^:renderer stepper\n  "Renderer maker: − and + buttons around this cell\'s number, in the\n  cell\'s format and unit. (stepper) steps by 1 of the cell\'s unit (1 km\n  in a km cell, else 1); (stepper 5) by 5; (stepper 1 0 10) stays within\n  0–10; (stepper \\"0.5 km\\") by half a km. Without bounds it keeps to the\n  cell\'s validation, e.g. (between 0 10)."\n  {:accepts #{:number :empty} :writes-own true :aka "plus minus spinner increment"\n   :refine [{:param :step :label "Step" :kind :number :min 0 :default 1 :placeholder "1 (or 5, 10, 0.1)"}]}\n  ([] (stepper nil))\n  ([step] (stepper step nil nil))\n  ([step lo hi]\n   (fn [v ctx]\n     (let [{cmin :min cmax :max} (:constraint ctx)\n           step (or (option-number step) (unit-step ctx))\n           lo (if (some? lo) (option-number lo) cmin)\n           hi (if (some? hi) (option-number hi) cmax)\n           bound #(cond-\x3e % lo (max lo) hi (min hi))\n           x (if (number? v) v 0)]\n       [:span.r-stepper\n        [:button {:on-click (fn [_] (set-self! ctx (bound (- x step))))} "−"]\n        (plain v ctx)\n        [:button {:on-click (fn [_] (set-self! ctx (bound (+ x step))))} "+"]]))))\n\n(defn ^:renderer toggle\n  "Renderer: a checkbox editing this cell\'s own true/false value. Use as:\n  toggle."\n  {:accepts #{:bool :empty} :writes-own true :aka "checkbox switch on off boolean"}\n  [v ctx]\n  [:input {:type "checkbox" :checked (boolean v)\n           :on-change (fn [e] (set-self! ctx (event-checked e)))}])\n\n(defn ^:renderer text-input\n  "Renderer: a text box editing this cell\'s own text. Use as: text-input."\n  {:accepts #{:text :empty} :writes-own true :aka "text box field typing"}\n  [v ctx]\n  [:input.text-input {:type "text" :value (str v)\n                      :on-change (fn [e] (set-self! ctx (event-value e)))}])\n\n(defn ^:renderer number-input\n  "Renderer: a number box editing this cell\'s own number (cleared, the\n  cell becomes empty). In a cell with a unit the number is in that unit\n  (5 for 5 km). Its arrows keep to the cell\'s validation, e.g. (between\n  0 10) or pos-int?. Use as: number-input."\n  {:accepts #{:number :empty} :writes-own true :aka "spinner number box field"}\n  [v ctx]\n  (let [u (:unit ctx)\n        shown #(when (number? %) (shown-number % ctx))\n        {:keys [min max step]} (:constraint ctx)]\n    [:input.text-input {:type "number" :value (if (number? v) (shown v) "")\n                        :min (shown min) :max (shown max)\n                        :step (or (when (number? step) (- (shown step) (shown 0))) "any")\n                        :on-change (fn [e] (let [n (str-\x3enum (event-value e))]\n                                             (set-self! ctx (if (and n u) (with-unit n u) n))))}]))\n\n(defn ^:renderer date-input\n  "Renderer: a date picker editing this cell\'s own date (a serial number,\n  written as if typed: 2026-11-07). Use as: date-input."\n  {:accepts #{:date :empty} :writes-own true :aka "calendar date picker"}\n  [v ctx]\n  [:input.text-input {:type "date" :value (or (iso-date v) "")\n                      :on-change (fn [e] (let [s (event-value e)] (set-self! ctx (when (seq s) s))))}])\n\n(defn ^:renderer time-input\n  "Renderer: a time picker editing this cell\'s own time (written as if\n  typed: 14:30). Use as: time-input."\n  {:accepts #{:time :empty} :writes-own true :aka "clock time picker"}\n  [v ctx]\n  [:input.text-input {:type "time"\n                      :value (or (some-\x3e (iso-time v) (subs 0 5)) "")\n                      :on-change (fn [e] (let [s (event-value e)] (set-self! ctx (when (seq s) s))))}])\n\n(defn ^:renderer date-time-input\n  "Renderer: a date and time picker editing this cell\'s own date and time\n  (written as if typed: 2026-11-07 14:30). Use as: date-time-input."\n  {:accepts #{:date :empty} :writes-own true :aka "calendar clock picker"}\n  [v ctx]\n  [:input.text-input {:type "datetime-local"\n                      :value (if-let [d (iso-date v)] (str d "T" (subs (iso-time v) 0 5)) "")\n                      :on-change (fn [e] (let [s (event-value e)] (set-self! ctx (when (seq s) s))))}])\n\n(defn ^:renderer color-input\n  "Renderer: a colour picker editing this cell\'s own colour, as a\n  \\"#rrggbb\\" string: a palette, the colours applied recently, a custom\n  one, and Apply. Use as: color-input."\n  {:accepts #{:text} :writes-own true :aka "colour color picker"}\n  [v ctx]\n  (let [v (if (and (string? v) (re-matches #"#[0-9a-fA-F]{6}" v)) v "#000000")]\n    (if-let [pick (:color-picker ctx)]\n      (pick v (fn [c] (set-self! ctx c)))\n      [:input.r-color {:type "color" :value v\n                       :on-change (fn [e] (set-self! ctx (event-value e)))}])))\n\n(defn- option-pairs\n  "[value label] pairs from a vector of values (labelled by themselves:\n  label nil, see constraint-pairs) or a map {value label}."\n  [options]\n  (if (map? options)\n    (vec options)\n    (mapv (fn [o] [o (when (string? o) o)]) options)))\n\n(defn- constraint-pairs\n  "Option pairs of a control: its own, else the options of the cell\'s\n  validation, e.g. (one-of D2:D9). A value without a label of its own is\n  labelled as the cell would show it: a number in its format and unit."\n  [pairs ctx]\n  (mapv (fn [[o label]] [o (cond (some? label) label\n                                 (number? o) (number-text o ctx)\n                                 :else (pr-str o))])\n        (or pairs (option-pairs (:options (:constraint ctx))))))\n\n(defn ^:renderer dropdown\n  "Renderer maker: a drop-down list editing this cell\'s own value:\n  (dropdown [\\"Low\\" \\"Medium\\" \\"High\\"]). Options can be any values\n  (numbers, keywords…), and the cell gets the value itself; a map\n  {value label} shows the labels: (dropdown {1 \\"One\\" 2 \\"Two\\"}).\n  Bare, dropdown (or (dropdown)) offers the options of the cell\'s\n  validation: give the cells {:valid \\"(one-of D2:D9)\\"}."\n  {:accepts #{:text :number :empty} :writes-own true :aka "select list choice combo pick"\n   :suggest (fn [info] (choice-sources "dropdown" info))\n   :refine [{:param :options :label "Options" :kind :list}]}\n  ([] (dropdown nil))\n  ([options]\n   (let [own (when (some? options) (option-pairs options))]\n     (fn [v ctx]\n       (let [pairs (constraint-pairs own ctx)\n             i (first (keep-indexed (fn [i [o]] (when (\x3d o v) i)) pairs))]\n         (into [:select.r-dropdown {:value (if i (str i) "")\n                                    :on-change (fn [e] (let [j (str-\x3enum (event-value e))]\n                                                         (when j (set-self! ctx (first (nth pairs j))))))}]\n               (cons (when-not i [:option {:value ""} (cond (nil? v) "" (number? v) (number-text v ctx) :else (str v))])\n                     (map-indexed (fn [j [_ label]] [:option {:value (str j)} label]) pairs)))))))\n  ([v ctx] ((dropdown nil) v ctx)))\n\n(defn ^:renderer radio\n  "Renderer maker: radio buttons editing this cell\'s own value, one per\n  option: (radio [:low :mid :high]), or (radio {1 \\"One\\" 2 \\"Two\\"}) with\n  labels. Bare, radio (or (radio)) offers the options of the cell\'s\n  validation, as dropdown does."\n  {:accepts #{:text :number :empty} :writes-own true :aka "options choice buttons pick"\n   :suggest (fn [info] (choice-sources "radio" info))\n   :refine [{:param :options :label "Options" :kind :list}]}\n  ([] (radio nil))\n  ([options]\n   (let [own (when (some? options) (option-pairs options))]\n     (fn [v ctx]\n       (into [:span.r-radio]\n             (map-indexed (fn [j [o label]]\n                            [:label [:input {:type "radio" :checked (\x3d o v)\n                                             :on-change (fn [_] (set-self! ctx o))}]\n                             label])\n                          (constraint-pairs own ctx))))))\n  ([v ctx] ((radio nil) v ctx)))\n\n;;; # Panels\n;;; A small UI of your own, in a grid of its own: (panel opts rows) lays\n;;; out rows of cells — values, or gadgets: controls bound to the\n;;; formula\'s options, buttons, several in one cell — generated however\n;;; you like (for, map …). Write it as a function in a grid\'s library and\n;;; call it from a cell: (my-panel orders), which becomes (my-panel orders\n;;; {:region "North"}) as its controls are used. The options are its\n;;; state: saved, copied and undone with the cell. filter-view and\n;;; group-view are panels.\n;;;\n;;;   (defn top-orders\n;;;     ([rows] (top-orders rows {}))\n;;;     ([rows {:keys [region n] :or {n 3} :as opts}]\n;;;      (panel opts\n;;;        (concat\n;;;          [(into ["Region"] (for [r [nil "North" "South"]]\n;;;                              (press (or r "All") [:region] r)))\n;;;           ["Show" (press "−" [:n] #(max 1 (dec (or % 3)))) n\n;;;                   (press "+" [:n] #(inc (or % 3)))]]\n;;;          (for [o (take n (sort-by :qty \x3e (cond-\x3e\x3e rows region\n;;;                                           (filter #(\x3d region (:region %))))))]\n;;;            [(:item o) (:qty o)])))))\n\n(defn- gadget\n  "A panel item that isn\'t a plain value: f, of the panel\'s options, gives\n  {:value v :draw (fn [ctx] hiccup)}."\n  [f]\n  {:recdep.panel/gadget f})\n\n(defn gadget?\n  "Whether x is a panel gadget (input, press, beside …) rather than a value."\n  [x]\n  (and (map? x) (contains? x :recdep.panel/gadget)))\n\n(defn- realize\n  "Item x of a panel with options o: {:value v :draw f}, :draw nil for a\n  plain value."\n  [o x]\n  (if (gadget? x) ((:recdep.panel/gadget x) o) {:value x}))\n\n(defn- draw-item\n  "A realized item\'s hiccup."\n  [{:keys [value draw]} ctx]\n  (if draw (draw ctx) (plain value (dissoc ctx :format))))\n\n(defn input\n  "Panel gadget: a control — any interactive renderer: (dropdown [...]),\n  (slider 0 10), toggle, text-input, (radio [...]) — editing option `path`\n  of the panel\'s formula: (input [:rate] (slider 0 0.1 0.005)). Its cell\'s\n  value is the option\'s."\n  [path control]\n  (gadget (fn [o] (let [cur (get-in o path)]\n                    {:value cur :draw (fn [ctx] (control cur (option-ctx ctx path)))}))))\n\n(defn press\n  "Panel gadget: a button labelled `label`. (press label path v) sets\n  option `path` to v, or, when v is a function, to (v current):\n  (press \\"+\\" [:n] inc), (press \\"All\\" [:region] nil); path [] is the\n  whole options map: (press \\"Reset\\" [] {}). (press label f) runs (f ctx)\n  when clicked, for anything else: (press \\"Go\\" #(set-cell! % \\"..\x3eA1\\" 1))."\n  ([label f] (gadget (fn [_] {:value label :draw (fn [ctx] ((button f) label ctx))})))\n  ([label path v]\n   (gadget (fn [o] (let [cur (if (empty? path) o (get-in o path))\n                         new (if (fn? v) (v cur) v)\n                         b (button (fn [ctx] (set-option! ctx path new)))]\n                     {:value label :draw (fn [ctx] (b label ctx))})))))\n\n(defn- several\n  "Items in one cell, laid out by the element `tag`; the cell\'s value is\n  the first item\'s."\n  [tag items]\n  (gadget (fn [o] (let [rs (mapv #(realize o %) items)]\n                    {:value (:value (first rs))\n                     :draw (fn [ctx] (into [tag] (map #(draw-item % ctx)) rs))}))))\n\n(defn beside\n  "Panel gadget: several items side by side in one cell, values and\n  gadgets: (beside \\"qty\\" (press \\"▲\\" [:sort] :up)). The cell\'s value is\n  the first item\'s."\n  [\x26 items]\n  (several :span.r-beside items))\n\n(defn stacked\n  "Panel gadget: several items one above another in one cell: (stacked\n  \\"Region\\" (input [:region] (dropdown [...]))). The cell\'s value is the\n  first item\'s."\n  [\x26 items]\n  (several :div.r-stacked items))\n\n(defn with-style\n  "Panel gadget: item x drawn with a CSS style: (with-style \\"Total\\"\n  {:font-weight 600})."\n  [x style]\n  (gadget (fn [o] (let [r (realize o x)]\n                    {:value (:value r) :draw (fn [ctx] [:span {:style style} (draw-item r ctx)])}))))\n\n(defn with-value\n  "Panel gadget: item x, but with cell value v (what references read, and\n  a header\'s column name): (with-value \\"region\\" (stacked \\"group by\\" …))."\n  [v x]\n  (gadget (fn [o] (assoc (realize o x) :value v))))\n\n(defn drawn\n  "Panel gadget: value v drawn by a renderer — a chart over data the panel\n  computed: (drawn (map :qty shown) bars). The cell\'s value is v. Give it\n  room with panel\'s :spans and :heights."\n  [v renderer]\n  (gadget (fn [_] {:value v :draw (fn [ctx] (renderer v ctx))})))\n\n(defn panel\n  "A small UI in a grid of its own (as-grid): `rows` of cells, each a value\n  or a gadget (input, press, drawn, beside, stacked, with-style,\n  with-value), with gadgets reading and writing the options map `opts` —\n  the last argument of the formula, which they rewrite. Options (a third\n  map): :value, the cell\'s value (else the cells\' values, as rows);\n  :headers true, row 1 as headers; :widths {0 120 …} and :heights {1 200\n  …}, column widths and row heights until the grid has its own; :spans\n  {[1 0] [1 4]}, cells drawn over a block of rows × columns (a chart\n  across the panel). Rows can be of different lengths. See the section\'s\n  example."\n  ([opts rows] (panel opts rows {}))\n  ([opts rows {:keys [headers widths heights spans] :as popts}]\n   (let [rs (mapv (fn [row] (mapv #(realize opts %) row)) rows)\n         renders (into {} (for [[r row] (map-indexed vector rs)\n                                [c it] (map-indexed vector row)\n                                :when (:draw it)]\n                            [[r c] (let [d (:draw it)] (fn [_ ctx] (d ctx)))]))\n         shown (mapv #(mapv :value %) rs)]\n     (as-grid (if (contains? popts :value) (:value popts) shown)\n              (cond-\x3e {:show shown :renders renders :widths widths :heights heights :spans spans}\n                (contains? popts :headers) (assoc :headers headers))))))\n\n;;; # Interactive views\n;;; Functions whose result is a grid with its own controls: a formula\n;;; such as (filter-view orders) makes a grid (as-grid) whose header row\n;;; holds drop-downs and buttons — the interactive renderers above,\n;;; composed. What they choose is kept in the formula\'s options map, its\n;;; last argument, which they rewrite: (filter-view orders {:region\n;;; "North" :sort [:qty :desc]}). Each choice is one undo step, is saved\n;;; and copied with the cell, and can be edited by hand.\n;;; A view marked ^:view, as these are, is offered by the Shelf tab for a\n;;; table it suits (dropped on a selection, in a new cell):\n;;; mark your own the same way, {:caption "…"} naming its tile and\n;;; {:columns [:region :qty]} the columns it reads.\n\n(defn- same-value?\n  "Whether a filter\'s value `want` matches x: text ignoring case."\n  [want x]\n  (if (and (string? want) (string? x))\n    (\x3d (clojure.string/lower-case want) (clojure.string/lower-case x))\n    (\x3d want x)))\n\n(defn- matching-rows\n  "The rows that every filter {column value} keeps."\n  [rows filters]\n  (filterv (fn [row] (every? (fn [[k want]] (same-value? want (get row k))) filters)) rows))\n\n(defn- filter-head\n  "Column k\'s header in a filter-view: its name and sort buttons over a\n  drop-down of its values (in the rows the other columns\' filters keep)."\n  [k others want [sk sd]]\n  (let [vals (sort excel-compare (distinct (remove nil? (map #(get % k) others))))\n        vals (if (and (some? want) (not (some #(same-value? want %) vals))) (cons want vals) vals)\n        sorter (fn [dir lit unlit]\n                 (let [on? (\x3d [sk sd] [k dir])]\n                   (press (if on? lit unlit) [:sort] (when-not on? [k dir]))))]\n    (stacked (beside (name k) (sorter :asc "▲" "△") (sorter :desc "▼" "▽"))\n             (input [k] (dropdown (apply array-map nil "(all)"\n                                         (mapcat (fn [x] [x (if (string? x) x (pr-str x))]) vals)))))))\n\n(defn ^:view filter-view\n  "A table in a grid of its own (as-grid) with a filter and sort buttons\n  on each column\'s header, as Excel\'s filter: (filter-view orders). Pick\n  a value from a column\'s drop-down to keep only its rows, (all) for\n  every row; △ ▽ sort by the column, and clicking the lit one again\n  stops sorting. The choices are written into the formula, (filter-view\n  orders {:region \\"North\\" :sort [:qty :desc]}), so they\'re saved,\n  undone and copied with it, and can be typed. The cell\'s value is the\n  rows shown; the source is never changed."\n  {:aka "filter sort autofilter" :caption "filter and sort"}\n  ([rows] (filter-view rows {}))\n  ([rows opts]\n   (when-not (or (empty? rows) (table-like? rows))\n     (throw (ex-info "filter-view needs a table: a grid with headers, or rows as maps" {})))\n   (let [cols (into [] (distinct) (mapcat keys rows))\n         sort-spec (:sort opts)\n         filters (dissoc opts :sort)\n         shown (cond-\x3e (matching-rows rows filters)\n                 sort-spec (sort-rows (first sort-spec) (or (second sort-spec) :asc)))]\n     (panel opts\n            (into [(mapv #(filter-head % (matching-rows rows (dissoc filters %)) (get filters %) sort-spec) cols)]\n                  (map (fn [row] (mapv #(get row %) cols)))\n                  shown)\n            {:value shown :headers true}))))\n\n(def ^:private summaries\n  "group-view\'s summaries, [label f] by the keyword its options use."\n  (let [nums #(seq (filter number? %))]\n    (array-map :sum ["Sum" #(reduce + 0 (filter number? %))]\n               :average ["Average" #(when-let [ns (nums %)] (/ (reduce + ns) (count ns)))]\n               :count ["Count" count]\n               :min ["Min" #(some-\x3e\x3e (nums %) (apply min))]\n               :max ["Max" #(some-\x3e\x3e (nums %) (apply max))]\n               :none ["—" (constantly nil)])))\n\n(defn- default-summary\n  "A column\'s summary when its options don\'t name one: sum numbers."\n  [rows k]\n  (let [xs (remove nil? (map #(get % k) rows))]\n    (if (and (seq xs) (every? number? xs)) :sum :none)))\n\n(defn ^:view group-view\n  "A table summarised by a column, in a grid of its own (as-grid), with\n  the choices on its header: (group-view orders). The first header\'s\n  drop-down picks the column to group by (a row per value, sorted); every\n  other column\'s picks its summary — Sum, Average, Count, Min, Max or —\n  (numbers are summed until you choose). The choices are written into\n  the formula, (group-view orders {:by :region :qty :sum :price\n  :average}), as filter-view\'s are."\n  {:aka "group by summarise summarize subtotal aggregate totals" :caption "group and summarise"}\n  ([rows] (group-view rows {}))\n  ([rows opts]\n   (when-not (or (empty? rows) (table-like? rows))\n     (throw (ex-info "group-view needs a table: a grid with headers, or rows as maps" {})))\n   (let [cols (into [] (distinct) (mapcat keys rows))\n         by (or (:by opts) (first cols))\n         _ (when-not (some #{by} cols)\n             (throw (ex-info (str "group-view: no column " (pr-str by)) {})))\n         others (vec (remove #{by} cols))\n         pick (fn [k] (let [s (get opts k (default-summary rows k))] (if (contains? summaries s) s :none)))\n         shown (when (seq rows)\n                 ;; (a column without a summary stays in the grid, empty, for its control)\n                 (group-rows rows by (into {} (keep (fn [k] (when-not (\x3d :none (pick k))\n                                                              [k (second (get summaries (pick k)))])))\n                                           others)))\n         o (into {:by by} (map (fn [k] [k (pick k)])) others)\n         by-pick (dropdown (apply array-map (mapcat (fn [k] [k (name k)]) cols)))\n         sum-pick (dropdown (apply array-map (mapcat (fn [[k [label]]] [k label]) summaries)))]\n     (panel o\n            (into [(into [(with-value (name by) (stacked "group by" (input [:by] by-pick)))]\n                         (map (fn [k] (stacked (name k) (input [k] sum-pick))))\n                         others)]\n                  (map (fn [row] (into [(get row by)] (map #(get row %)) others)))\n                  (or shown []))\n            {:value (or shown []) :headers true}))))\n\n(defn- numeric-column?\n  "Whether every value in column k of the rows is a number (and one is)."\n  [rows k]\n  (let [xs (remove nil? (map #(get % k) rows))]\n    (and (seq xs) (every? number? xs))))\n\n(defn ^:view pivot-view\n  "A cross-table of a table, in a grid of its own (as-grid), with its\n  choices in a row of controls above it, one per cell: (pivot-view\n  orders). A row per\n  value of the rows column, a column per value of the columns column\n  ((none) for one column), and in each cell the summary — Sum, Average,\n  Count, Min or Max — of the values column in the rows with both; the\n  totals checkbox adds a Total row and column. The choices are written\n  into the formula, (pivot-view orders {:rows :region :cols :month\n  :value :qty :f :sum :totals true}), as filter-view\'s are. The cell\'s\n  value is the cross-table, header row first (row 2 of the grid: row 1\n  is the controls), so (SUM pv) and pv\x3eB3 work."\n  {:aka "pivot table crosstab cross-tab matrix" :caption "cross-table"}\n  ([rows] (pivot-view rows {}))\n  ([rows opts]\n   (when-not (or (empty? rows) (table-like? rows))\n     (throw (ex-info "pivot-view needs a table: a grid with headers, or rows as maps" {})))\n   (let [cols (into [] (distinct) (mapcat keys rows))\n         labels (remove #(numeric-column? rows %) cols)\n         need (fn [what k]\n                (when-not (some #{k} cols)\n                  (throw (ex-info (str "pivot-view: no column " (pr-str k) " for " what) {})))\n                k)\n         rk (need ":rows" (or (:rows opts) (first labels) (first cols)))\n         ck (let [c (if (contains? opts :cols) (:cols opts) (first (remove #{rk} labels)))]\n              (when-not (or (nil? c) (\x3d :none c) (\x3d c rk)) (need ":cols" c)))\n         vk (need ":value" (or (:value opts)\n                               (first (filter #(numeric-column? rows %) (remove #{rk ck} cols)))\n                               (first (remove #{rk ck} cols))\n                               rk))\n         fk (let [f (get opts :f :sum)] (if (and (contains? summaries f) (not\x3d :none f)) f :sum))\n         totals? (get opts :totals true)\n         [flabel f] (get summaries fk)\n         blank #(if (nil? %) "(blank)" %)\n         rg #(blank (get % rk))\n         cg (if ck #(blank (get % ck)) (constantly nil))\n         rks (sort excel-compare (distinct (map rg rows)))\n         cks (if ck (sort excel-compare (distinct (map cg rows))) [nil])\n         by (group-by (juxt rg cg) rows)\n         by-r (group-by rg rows)\n         by-c (group-by cg rows)\n         cell (fn [g] (when (seq g) (f (vec (remove nil? (map #(get % vk) g))))))\n         total-col? (and totals? ck)\n         head (cond-\x3e (into [(name rk)] (if ck cks [(str flabel " of " (name vk))]))\n                total-col? (conj "Total"))\n         body (for [r rks]\n                (cond-\x3e (into [r] (map #(cell (get by [r %]))) cks)\n                  total-col? (conj (cell (get by-r r)))))\n         foot (when (and totals? (seq rows))\n                [(cond-\x3e (into ["Total"] (map #(cell (get by-c %))) cks)\n                   total-col? (conj (cell rows)))])\n         table (-\x3e [head] (into body) (into foot))\n         o {:rows rk :cols (or ck :none) :value vk :f fk :totals totals?}\n         pick (fn [ks] (dropdown (apply array-map (mapcat (fn [k] [k (name k)]) ks))))\n         f-pick (dropdown (apply array-map (mapcat (fn [[k [label]]] [k label]) (dissoc summaries :none))))]\n     (panel o\n            (into [[(stacked "rows" (input [:rows] (pick cols)))\n                    (stacked "columns" (input [:cols] (dropdown (apply array-map :none "(none)"\n                                                                       (mapcat (fn [k] [k (name k)]) (remove #{rk} cols))))))\n                    (stacked "summary" (input [:f] f-pick))\n                    (stacked "of" (input [:value] (pick cols)))\n                    (stacked "totals" (input [:totals] toggle))]]\n                  table)\n            ;; one width for every column, as the controls take one cell each\n            {:value table :headers false\n             :widths (into {} (map (fn [c] [c 90])) (range (max 5 (count head))))}))))\n\n;;; # Grids in cells\n;;; A cell holding a grid gets, in ctx: :grid {:rows :cols}; :zoom!, which\n;;; shows the grid in the main area; :show-grid, which returns the live\n;;; grid as hiccup ((show) for all of it, (show rows cols) for a window);\n;;; and :error when something inside has an error (the value is then nil).\n\n(defn ^:renderer instance-view\n  "Renderer: an instance, (instance Loan {...}), drawn as its template\'s\n  grid with the instance\'s values, through the template\'s renderers and\n  formats; its inputs can be changed in place, which rewrites the\n  overrides. The default for an instance. Over it, a line with a link to\n  the template and how many values are its own; left off when the\n  template presents itself (has a display area), as its grid cell is\n  drawn clean. (instance-view {:head false}) leaves it off, {:head true}\n  puts it on, whatever the template. Use as: instance-view, or\n  (instance-view {:head false})."\n  ([opts] (fn [v ctx] (if-let [show (:show-instance ctx)] (show opts) (key-values v ctx))))\n  ([v ctx] (if-let [show (:show-instance ctx)] (show) (key-values v ctx))))\n\n(defn ^:renderer grid-link\n  "Renderer: the default for a grid cell — a button that zooms into the\n  grid (same as In, Alt-Down or Enter). Use as: grid-link."\n  {:accepts #{:grid} :aka "zoom link open"}\n  [v ctx]\n  (let [{:keys [rows cols]} (:grid ctx)]\n    [:button.grid-link {:title "Zoom into this grid (same as In, Alt-Down, Enter)"\n                        :on-click (fn [_] ((:zoom! ctx)))}\n     (str "▦ " rows "×" cols " grid ›")]))\n\n(defn- value-grid\n  "grid-view on a cell without a grid: a 2-D value or a table as a table\n  filling the cell, as a grid\'s view does."\n  [v ctx]\n  (if (or (table-like? v) (and (sequential? v) (seq v) (every? sequential? v)))\n    (assoc (table v ctx) 0 :table.value-table.value-grid)\n    (plain v ctx)))\n\n(defn ^:renderer grid-view\n  "Renderer maker: show the grid inside its cell, live and editable,\n  filling the cell. (grid-view) shows all of it; (grid-view rows cols)\n  keeps that many rows and columns in view and scrolls for the rest. A\n  grid whose author marked a display area inside it (right-click a block\n  in it: Show only this in the grid\'s cell) shows only that block, the\n  rest working out of sight: its scratch cells.\n  Widen the column (or set the row\'s height) and the cells grow. On a\n  cell without a grid, a 2-D value or a table of row maps (a formula\'s\n  result) is drawn as a table, as big as the value; anything else plain."\n  {:accepts #{:grid :table :rows} :aka "show grid inline table"\n   :refine [{:param :rows :label "Rows in view" :kind :int :min 1 :max 100 :fill 5}\n             {:param :cols :label "Columns in view" :kind :int :min 1 :max 50 :fill 3}]}\n  ([] (fn [v ctx] (if-let [show (:show-grid ctx)] (show) (value-grid v ctx))))\n  ([rows cols] (fn [v ctx] (if-let [show (:show-grid ctx)] (show rows cols) (value-grid v ctx)))))\n\n;;; # Tests\n;;; A cell that checks the sheet: (assert\x3d B4 1000) passes when B4 is\n;;; 1000, and shows ✓; when it isn\'t, ✗ with what B4 is. assert-near\n;;; allows a tolerance, assert-true takes any condition, and each takes a\n;;; message saying what\'s tested. Tests re-run with every change, like any\n;;; formula. The Tests tab lists every test in the sheet, failing first,\n;;; and the status bar counts the failures; a click goes to each. A test\'s\n;;; result is a value, not an error: formulas reading it go on computing,\n;;; and a grid holding a failing test still works. To test a grid used as\n;;; a function, call it: (assert\x3d (call $E$32 {:rate 0} :total) 1000), or\n;;; give the grid test cases of its own in the Tests tab: inputs and the\n;;; outputs they should give, kept with the grid.\n\n(defn ^:renderer test-result\n  "Renderer: a test\'s result as ✓ when it passes, ✗ and why when it\n  fails (several results: how many). The default renderer draws tests\n  with it. Use as: test-result."\n  [v ctx]\n  (if-let [{:keys [pass? n msg]} (test-outcome v)]\n    (if pass?\n      [:span.r-test.pass {:title (or msg "passes")} (if (\x3e n 1) (str "✓ " n) "✓")]\n      [:span.r-test.fail {:title msg} "✗ " msg])\n    (plain v ctx)))\n\n;;; # Cells that update over time\n;;; NOW, TODAY, RAND and the like are computed when their formula is: F9\n;;; (or ↻ in the status bar) computes every cell using them again, with\n;;; what depends on them. (tick 1000) is the time now, and its cell runs\n;;; again every second: the cells reading it follow, for clocks,\n;;; simulations and live dashboards. (history B5 50) keeps B5\'s last 50\n;;; values, for a sparkline or a moving average. The status bar pauses\n;;; the timers.\n\n;;; # Uncertain inputs (Monte Carlo)\n;;; A number you can only estimate can say so: (normal 100 15),\n;;; (triangular 800 1000 1500), (uniform 11 13), (chance 0.1). On the\n;;; sheet such a cell shows its mean, so the model reads as it always did.\n;;; (simulate profit 1000) works profit out 1000 times, each time with a\n;;; fresh draw from every uncertain input it depends on, however far\n;;; upstream, and gives the 1000 results, drawn as a histogram. The draws\n;;; come from a fixed seed: the result changes when the model does, not\n;;; on every edit, and two simulations see the same draws, run by run.\n;;; Read the results with stats, chance-of, or Excel\'s AVERAGE, MEDIAN,\n;;; STDEV.S and PERCENTILE.INC; draw them with histogram or band.\n\n(defn- stats-title\n  "The tooltip of a simulation\'s chart: mean, middle 90%, runs."\n  [{:keys [n mean p5 p50 p95]} ctx]\n  (str "mean " (short-number mean ctx) " · median " (short-number p50 ctx)\n       " · 90% of runs from " (short-number p5 ctx) " to " (short-number p95 ctx) " · " n " runs"))\n\n(defn ^:renderer histogram\n  "Renderer: a histogram of the numbers in the value — a simulation\'s\n  runs, or any range or list — in 24 bins, the outer 5% at each end paler,\n  a line at the mean; hover for the mean, median and middle 90%. The\n  default renderer draws simulate\'s results with it. Use as: histogram."\n  {:accepts #{:seq} :aka "distribution frequency simulation"}\n  [v ctx]\n  (let [s (stats v)]\n    (if (nil? s)\n      [:span.muted "no numbers"]\n      (let [{:keys [lo hi counts]} (bin-counts v 24)\n            n (count counts) top (apply max counts)\n            w 100 h 40 bw (/ w n)\n            x-of (fn [x] (if (\x3d hi lo) (/ w 2) (* w (/ (- x lo) (- hi lo)))))\n            mid (fn [i] (+ lo (* (+ i 0.5) (/ (- hi lo) n))))]\n        (into [:svg.chart.r-histogram {:viewBox (str "0 0 " w " " h) :preserveAspectRatio "none"}\n               [:title (stats-title s ctx)]]\n              (concat\n                (map-indexed\n                  (fn [i k]\n                    (let [bh (* (- h 2) (/ k top))]\n                      [:rect {:x (+ (* i bw) (* 0.06 bw)) :width (* 0.88 bw) :y (- h bh) :height bh\n                              :class (if (\x3c\x3d (:p5 s) (mid i) (:p95 s)) "pos" "tail")}]))\n                  counts)\n                [[:line.mean {:x1 (x-of (:mean s)) :x2 (x-of (:mean s)) :y1 0 :y2 h}]]))))))\n\n(defn ^:renderer band\n  "Renderer: a percentile band of the numbers in the value (a\n  simulation\'s runs): the line runs from the 5th to the 95th percentile,\n  the box from the 25th to the 75th, a tick at the median and a dot at\n  the mean, between the least and greatest run; the 5th and 95th are\n  written at the ends. Use as: band."\n  {:accepts #{:seq} :aka "percentile range box plot uncertainty"}\n  [v ctx]\n  (let [s (stats v)]\n    (if (nil? s)\n      [:span.muted "no numbers"]\n      (let [{:keys [min max p5 p25 p50 p75 p95 mean]} s\n            w 100 h 20\n            x (fn [v] (if (\x3d max min) (/ w 2) (* w (/ (- v min) (- max min)))))]\n        [:div.r-band {:title (stats-title s ctx)}\n         [:span.lo (short-number p5 ctx)]\n         [:svg {:viewBox (str "0 0 " w " " h) :preserveAspectRatio "none"}\n          [:line.whisker {:x1 (x p5) :x2 (x p95) :y1 (/ h 2) :y2 (/ h 2)}]\n          [:rect.box {:x (x p25) :width (clojure.core/max 0.5 (- (x p75) (x p25))) :y 4 :height (- h 8)}]\n          [:line.median {:x1 (x p50) :x2 (x p50) :y1 2 :y2 (- h 2)}]\n          [:circle.mean {:cx (x mean) :cy (/ h 2) :r 1.6}]]\n         [:span.hi (short-number p95 ctx)]]))))\n\n;;; # Default renderer\n;;; What a cell without a renderer of its own (or of its column, row or\n;;; range) is drawn with. Redefine default-render in a grid\'s library to\n;;; change it for that grid and the grids inside it.\n\n(defn grid-like?\n  "Whether v is a non-empty vector of vectors — a 2-D value that the\n  default renderer shows as a table."\n  [v]\n  (and (vector? v) (seq v) (every? vector? v)))\n\n(defn ^:renderer default-render\n  "Renderer used when a cell has none of its own: grid-link for a grid\n  cell, table for a 2-D value or a table of row maps, λ for a function,\n  test-result for a test, histogram for simulate\'s results, plain (in\n  the cell\'s number format) for anything else."\n  [v ctx]\n  (cond (:grid ctx)    (grid-link v ctx)\n        (:show-instance ctx) (instance-view v ctx)\n        (grid-like? v) (table v ctx)\n        (table-like? v) (table v ctx)\n        (fn? v)        [:span.fn "λ"]\n        (test-outcome v) (test-result v ctx)\n        (samples? v)   (if (some number? v)\n                         (histogram v ctx)\n                         [:span.code {:title "a simulation\'s runs that aren\'t numbers: (map first …) picks a number from each"}\n                          (str (count v) " runs: " (pr-str (first v)) " …")])\n        :else          (plain v ctx)))\n'))},null);
